	--callout-padding: var(--prime-callout-padding);
	--callout-title-color: var(--prime-callout-title-color);
	--callout-title-size: var(--prime-callout-title-size);
	--callout-title-weight: var(--prime-callout-title-weight);

	/* ── Tables ──────────────────────────────────────────────────────── */
	--table-border-color: var(--prime-table-border-color);
	--table-border-width: var(--prime-table-border-width);
	--table-header-background: var(--prime-table-header-bg);
	--table-header-color: var(--prime-table-header-color);
	--table-header-weight: var(--prime-table-header-weight);
	--table-row-alt-background: var(--prime-table-stripe-bg);
	--table-row-background-hover: var(--prime-table-row-hover-bg);
	--table-cell-padding: var(--prime-table-cell-padding);

	/* ── Lists ───────────────────────────────────────────────────────── */
	--list-marker-color: var(--prime-list-marker-color);
	--list-indent-guide-color: color-mix(
		in srgb,
		var(--prime-list-indent-color) 35%,
		transparent
	);

	/* ── Embeds ──────────────────────────────────────────────────────── */
	--embed-background: var(--prime-embed-bg);
	--embed-border-left: var(--prime-embed-border-width) solid var(--prime-embed-border-color);
	--embed-padding: 0;
	--embed-font-style: inherit;

	/* ── Metadata / properties ───────────────────────────────────────── */
	--metadata-background: var(--prime-props-bg);
	--metadata-label-text-color: var(--prime-props-key-color);
	--metadata-input-text-color: var(--prime-props-value-color);
	--metadata-divider-color: var(--prime-border);

	/* ── Chrome ──────────────────────────────────────────────────────── */
	--titlebar-background: var(--prime-titlebar-bg);
	--titlebar-background-focused: var(--prime-titlebar-bg);
	--titlebar-text-color: var(--prime-text-muted);
	--titlebar-text-color-focused: var(--prime-accent);
	--titlebar-border-color: var(--prime-border);

	--status-bar-background: var(--prime-statusbar-bg);
	--status-bar-text-color: var(--prime-text-muted);
	--status-bar-border-color: var(--prime-border);

	--ribbon-background: var(--prime-bg-primary-alt);
	--ribbon-background-collapsed: var(--prime-bg-primary-alt);

	--tab-background-active: var(--prime-bg-primary);
	--tab-text-color: var(--prime-text-muted);
	--tab-text-color-active: var(--prime-accent);
	--tab-text-color-focused-active: var(--prime-accent);
	--tab-text-color-focused-highlighted: var(--prime-accent);
	--tab-radius-active: var(--prime-tab-radius);
	--tab-outline-color: var(--prime-border);

	--nav-item-color: var(--prime-text-muted);
	--nav-item-color-hover: var(--prime-accent);
	--nav-item-color-active: var(--prime-accent);
	--nav-item-color-selected: var(--prime-accent);
	--nav-item-background-hover: var(--prime-surface-hover);
	--nav-item-background-active: var(--prime-surface-active);
	--nav-item-background-selected: var(--prime-surface-selected);

	--modal-background: var(--prime-bg-elevated);
	--modal-border-color: var(--prime-border);
	--modal-radius: var(--prime-modal-radius);

	--prompt-border-color: var(--prime-border);
	--divider-color: var(--prime-border);
	--divider-color-hover: var(--prime-border-hover);

	--icon-color: var(--prime-text-muted);
	--icon-color-hover: var(--prime-accent);
	--icon-color-active: var(--prime-accent);
	--icon-color-focused: var(--prime-accent);
	--icon-opacity: var(--prime-icon-opacity);
	--icon-opacity-hover: var(--prime-icon-opacity-hover);
	--icon-opacity-active: 1;

	--input-radius: var(--prime-input-radius);
	--button-radius: var(--prime-button-radius);

	--scrollbar-thumb-bg: var(--prime-scrollbar-thumb);
	--scrollbar-active-thumb-bg: var(--prime-scrollbar-thumb-hover);
	--scrollbar-bg: transparent;

	--hr-color: var(--prime-divider-color);
	--hr-thickness: var(--prime-divider-thickness);

	--indentation-guide-color: color-mix(
		in srgb,
		var(--prime-list-indent-color) 30%,
		transparent
	);
	--indentation-guide-color-active: color-mix(
		in srgb,
		var(--prime-list-indent-color) 70%,
		transparent
	);

	--file-line-width: var(--prime-content-width);

	--graph-line: var(--prime-border-strong);
	--graph-node: var(--prime-text-muted);
	--graph-node-focused: var(--prime-accent);
	--graph-node-tag: var(--prime-accent-alt);
	--graph-node-attachment: var(--prime-color-green);

	--canvas-color-1: var(--prime-accent-rgb);
	--canvas-dot-pattern: var(--prime-border);
}

/* ── BASE · RESET ──────────────────────────────────────────────────────── */

/* ── Scrollbars ───────────────────────────────────────────────────────── */

::-webkit-scrollbar {
	width: var(--prime-scrollbar-width);
	height: var(--prime-scrollbar-width);
}

::-webkit-scrollbar-track,
::-webkit-scrollbar-track-piece,
::-webkit-scrollbar-corner {
	background: transparent;
}

::-webkit-scrollbar-thumb {
	background-color: var(--prime-scrollbar-thumb);
	border-radius: var(--prime-scrollbar-radius);
	border: 2px solid transparent;
	background-clip: padding-box;
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

::-webkit-scrollbar-thumb:hover {
	background-color: var(--prime-scrollbar-thumb-hover);
}

/* ── Selection ────────────────────────────────────────────────────────── */

::selection {
	background-color: var(--prime-selection-bg);
}

.markdown-source-view.mod-cm6 .cm-selectionBackground,
.markdown-source-view.mod-cm6 .cm-line .cm-selection,
.markdown-source-view.mod-cm6 .cm-editor > .cm-scroller > .cm-selectionLayer > .cm-selectionBackground {
	background-color: var(--prime-selection-bg);
}

/* ── Focus ────────────────────────────────────────────────────────────────
 * Accessibility: a visible focus ring on every interactive element.
 * Neither source theme provided one consistently. */

:focus-visible {
	outline: 2px solid var(--prime-border-focus);
	outline-offset: 2px;
	border-radius: var(--prime-radius-xs);
}

/* ── Cursor ───────────────────────────────────────────────────────────── */

.clickable-icon,
.nav-file-title,
.nav-folder-title,
button,
.checkbox-container,
input[type='checkbox'],
.workspace-tab-header,
.side-dock-ribbon-action {
	cursor: var(--prime-cursor);
}

/* ── BASE · TYPOGRAPHY ─────────────────────────────────────────────────── */

body {
	--font-text: var(--prime-font-text);
	--font-interface: var(--prime-font-interface);
	--font-monospace: var(--prime-font-monospace);
	font-family: var(--prime-font-interface);
}

.markdown-rendered,
.markdown-source-view.mod-cm6 .cm-scroller,
.markdown-preview-view {
	font-family: var(--prime-font-text);
	font-size: var(--prime-font-size);
	font-weight: var(--prime-font-weight);
	line-height: var(--prime-line-height);
	color: var(--prime-text-normal);
}

.markdown-rendered p,
.markdown-source-view.mod-cm6 .cm-line {
	line-height: var(--prime-line-height);
}

/* Monospace surfaces */
code,
pre,
kbd,
samp,
.HyperMD-codeblock,
.cm-inline-code,
.markdown-rendered .math {
	font-family: var(--prime-font-monospace);
	font-variant-ligatures: contextual;
}

/* ── <kbd> ────────────────────────────────────────────────────────────────
 * Obsidianite carried a bare `-webkit-text-fill-color: initial` here as an
 * escape hatch for its gradient-bold rule. Prime keeps the reset (it is still
 * correct and necessary) but now also gives <kbd> a real visual treatment —
 * and the systemic fix in 54-inline-code.css means the reset is defence in
 * depth rather than the only thing standing between the user and invisible
 * text. See docs/05 §2.3. */

kbd {
	-webkit-text-fill-color: initial;
	display: inline-block;
	padding: 0.1em 0.4em;
	font-size: 0.82em;
	font-family: var(--prime-font-monospace);
	line-height: 1.4;
	color: var(--prime-text-normal);
	background-color: var(--prime-bg-elevated);
	border: 1px solid var(--prime-border-strong);
	border-bottom-width: 2px;
	border-radius: var(--prime-radius-xs);
	vertical-align: baseline;
}

/* ── UI · WORKSPACE, RIBBON, SIDEBARS ──────────────────────────────────── */

.workspace {
	background-color: var(--prime-bg-primary-alt);
}

/* ── Ribbon ───────────────────────────────────────────────────────────── */

.workspace-ribbon {
	background-color: var(--prime-bg-primary-alt);
	border-color: var(--prime-border);
}

.workspace-ribbon.mod-left.is-collapsed,
.workspace-ribbon.mod-right.is-collapsed {
	border-color: var(--prime-border);
}

/* Clean-room motion: icons rest at reduced opacity and resolve to the accent
 * on hover. Obsidianite used `transition: all` (banned by PR-1); Prime lists
 * the animated properties explicitly. */
.side-dock-ribbon-action,
.side-dock-ribbon-tab,
.workspace-ribbon-collapse-btn,
.sidebar-toggle-button {
	opacity: var(--prime-icon-opacity);
	transition: opacity var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard),
		background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.side-dock-ribbon-action:hover,
.side-dock-ribbon-tab:hover,
.workspace-ribbon-collapse-btn:hover,
.sidebar-toggle-button:hover {
	opacity: var(--prime-icon-opacity-hover);
	color: var(--prime-accent);
}

/* ── Split / leaf ─────────────────────────────────────────────────────── */

.workspace-split.mod-root .workspace-leaf {
	background-color: var(--prime-bg-primary);
}

.workspace-leaf-content {
	background-color: var(--prime-bg-primary);
}

.workspace-split.mod-left-split .workspace-leaf-content,
.workspace-split.mod-right-split .workspace-leaf-content {
	background-color: var(--prime-bg-primary-alt);
}

.workspace-drop-overlay::before {
	background-color: var(--prime-surface-selected);
	border-radius: var(--prime-radius-m);
}

.workspace-leaf-resize-handle {
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.workspace-leaf-resize-handle:hover {
	background-color: var(--prime-accent);
}

/* ── View header ──────────────────────────────────────────────────────── */

.view-header {
	background-color: transparent;
	border-bottom: var(--prime-border-width) solid var(--prime-border);
}

.view-header-title {
	color: var(--prime-text-muted);
	font-weight: var(--prime-font-weight-medium);
	transition: color var(--prime-motion-fast) var(--prime-ease-standard);
}

.workspace-leaf.mod-active .view-header-title {
	color: var(--prime-accent);
}

.view-header-icon {
	color: var(--prime-text-muted);
}

.workspace-leaf.mod-active .view-header-icon {
	color: var(--prime-accent);
}

/* ── Vault profile ────────────────────────────────────────────────────── */

.workspace-sidedock-vault-profile {
	border-top: var(--prime-border-width) solid var(--prime-border);
	color: var(--prime-text-muted);
}

/* ── UI · TITLEBAR & STATUS BAR ────────────────────────────────────────── */

.titlebar {
	background-color: var(--prime-titlebar-bg);
}

.titlebar-text {
	color: var(--prime-accent);
}

.titlebar-button:hover {
	background-color: var(--prime-surface-hover);
	color: var(--prime-accent);
}

/* ── Status bar ───────────────────────────────────────────────────────────
 * Obsidianite's floating, fade-on-hover status bar is one of its nicest
 * touches (keeper K-8). Prime keeps it as the default and exposes a Docked
 * variant via Style Settings (body.prime-statusbar-docked). */

.status-bar {
	background-color: var(--prime-statusbar-bg);
	border-top: var(--prime-border-width) solid var(--prime-border);
	color: var(--prime-text-muted);
	transition: opacity var(--prime-motion-moderate) var(--prime-ease-standard);
}

body.prime-statusbar-floating .status-bar {
	position: absolute;
	right: 0;
	bottom: 0;
	margin: auto;
	display: flex;
	align-items: center;
	max-height: unset;
	padding: 6px 10px;
	border-top-left-radius: var(--prime-statusbar-radius);
	border-left: var(--prime-border-width) solid var(--prime-border);
	opacity: var(--prime-statusbar-opacity);
}

body.prime-statusbar-floating .status-bar:hover {
	opacity: var(--prime-statusbar-opacity-hover);
}

body.prime-statusbar-docked .status-bar {
	opacity: 1;
}

.status-bar-item {
	color: var(--prime-text-muted);
}

.status-bar-item.mod-clickable:hover {
	color: var(--prime-accent);
}

/* ── UI · TABS ─────────────────────────────────────────────────────────── */

.workspace-tab-header-container {
	background-color: var(--prime-bg-primary-alt);
	border-bottom: var(--prime-border-width) solid var(--prime-border);
}

.workspace-tab-header {
	opacity: 0.6;
	transition: opacity var(--prime-motion-fast) var(--prime-ease-standard),
		background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.workspace-tab-header:hover {
	opacity: 1;
}

.workspace-tab-header.is-active {
	opacity: 1;
}

.workspace-tab-header-inner {
	border-radius: var(--prime-tab-radius);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

.workspace-tab-header.is-active .workspace-tab-header-inner {
	background-color: var(--prime-surface-active);
}

.workspace-tab-header.is-active .workspace-tab-header-inner-icon,
.workspace-tab-header.is-active .workspace-tab-header-inner-title {
	color: var(--prime-accent);
}

.workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner {
	background-color: var(--prime-surface-hover);
}

/* Active-tab accent underline */
.workspace-tabs .workspace-tab-header.is-active::after {
	content: '';
	position: absolute;
	inset: auto 20% 0 20%;
	height: 2px;
	border-radius: var(--prime-radius-pill);
	background-color: var(--prime-accent);
	transition: opacity var(--prime-motion-fast) var(--prime-ease-standard);
}

.workspace-tab-header-new-tab .workspace-tab-header-inner-icon:hover {
	color: var(--prime-accent);
}

/* ── UI · FILE EXPLORER, SEARCH, OUTLINE, BACKLINKS ────────────────────── */

.nav-file-title,
.nav-folder-title {
	border: var(--prime-border-width) solid transparent;
	border-radius: var(--prime-radius-s);
	color: var(--prime-text-muted);
	transition: color var(--prime-motion-fast) var(--prime-ease-standard),
		background-color var(--prime-motion-fast) var(--prime-ease-standard),
		border-color var(--prime-motion-fast) var(--prime-ease-standard);
}

body:not(.is-grabbing) .nav-file-title:hover,
body:not(.is-grabbing) .nav-folder-title:hover {
	color: var(--prime-accent);
	background-color: var(--prime-surface-hover);
	border-color: var(--prime-border-hover);
}

.nav-file-title.is-active,
.nav-folder-title.is-active,
.tree-item-self.is-active {
	color: var(--prime-accent);
	background-color: var(--prime-surface-selected);
	border-color: var(--prime-border-strong);
}

.nav-folder.mod-root > .nav-folder-title {
	color: var(--prime-accent);
	font-weight: var(--prime-font-weight-semibold);
}

.nav-folder-collapse-indicator,
.tree-item-icon.collapse-icon {
	color: var(--prime-accent);
	transition: transform var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

.nav-file-tag {
	color: var(--prime-accent);
	background-color: var(--prime-tag-bg);
	border-radius: var(--prime-radius-xs);
}

/* ── Search ───────────────────────────────────────────────────────────── */

.search-input-container input,
.search-input-container input:active,
.search-input-container input:focus {
	border-radius: var(--prime-input-radius);
	background-color: var(--prime-bg-secondary);
	transition: box-shadow var(--prime-motion-fast) var(--prime-ease-standard),
		background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.search-result-file-title {
	color: var(--prime-accent);
	font-weight: var(--prime-font-weight-medium);
}

.search-result-file-match {
	border-radius: var(--prime-radius-s);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.search-result-file-match:hover {
	background-color: var(--prime-surface-hover);
}

.search-result-file-matched-text,
.suggestion-highlight {
	color: var(--prime-highlight-text);
	background-color: var(--prime-search-bg);
	border-radius: var(--prime-radius-xs);
}

.tree-item-flair,
.pane-list-item-ending-flair {
	color: var(--prime-text-faint);
	transition: color var(--prime-motion-fast) var(--prime-ease-standard);
}

.tree-item-self:hover .tree-item-flair {
	color: var(--prime-accent);
}

/* ── Outline & backlinks ──────────────────────────────────────────────── */

.outline .tree-item-inner,
.backlink-pane .tree-item-inner {
	color: var(--prime-text-muted);
}

.outline .tree-item-self:hover .tree-item-inner,
.backlink-pane .tree-item-self:hover .tree-item-inner {
	color: var(--prime-accent);
}

/* ── Tag pane ─────────────────────────────────────────────────────────── */

.tag-pane-tag-text {
	color: var(--prime-accent);
}

.tag-pane-tag-count {
	color: var(--prime-text-faint);
	background-color: var(--prime-bg-secondary);
	border-radius: var(--prime-radius-pill);
}

/* ── UI · MODALS, POPOVERS, SUGGESTERS, NOTICES ────────────────────────── */

.modal,
.prompt,
.suggestion-container,
.menu {
	background-color: var(--prime-bg-elevated);
	border: var(--prime-border-width) solid var(--prime-border-strong);
	border-radius: var(--prime-modal-radius);
	box-shadow: var(--prime-shadow-l);
}

/* Clean-room entry motion. Independently authored keyframes live in
 * src/systems/81-motion.css. Gated behind the animation master toggle and
 * prefers-reduced-motion. */
body:not(.prime-animations-off) :is(.modal, .prompt, .suggestion-container, .menu) {
	animation: prime-enter-up var(--prime-motion-moderate) var(--prime-ease-overshoot) both;
}

body.prime-anim-no-popups :is(.modal, .prompt, .suggestion-container, .menu) {
	animation: none;
}

.modal-bg,
.prompt-bg {
	background-color: hsl(255 26% 3% / 0.55);
}

body.prime-no-blur .modal-bg,
body.prime-no-blur .prompt-bg {
	backdrop-filter: none;
}

.modal-title {
	color: var(--prime-accent);
	font-weight: var(--prime-font-weight-semibold);
}

.modal-close-button {
	transition: color var(--prime-motion-fast) var(--prime-ease-standard);
}

.modal-close-button:hover {
	color: var(--prime-accent);
}

/* ── Suggestions ──────────────────────────────────────────────────────── */

.suggestion-item {
	border-radius: var(--prime-radius-s);
	transition: background-color var(--prime-motion-superfast) var(--prime-ease-standard),
		color var(--prime-motion-superfast) var(--prime-ease-standard);
}

.suggestion-item.is-selected {
	background-color: var(--prime-surface-selected);
	color: var(--prime-accent);
}

.suggestion-flair,
.suggestion-note {
	color: var(--prime-text-faint);
}

/* ── Menus ────────────────────────────────────────────────────────────── */

.menu-item {
	border-radius: var(--prime-radius-s);
	transition: background-color var(--prime-motion-superfast) var(--prime-ease-standard),
		color var(--prime-motion-superfast) var(--prime-ease-standard);
}

.menu-item:hover:not(.is-disabled):not(.is-label) {
	background-color: var(--prime-surface-hover);
	color: var(--prime-accent);
}

.menu-separator {
	border-color: var(--prime-border);
}

/* ── Hover popover ────────────────────────────────────────────────────────
 * Note: hover popovers render markdown into .markdown-rendered WITHOUT
 * .markdown-preview-view. Prime's component rules target .markdown-rendered
 * precisely so that inline code, headings and the rest are styled here.
 * This is one half of the Bug #2 secondary fix. See docs/05 §4. */

.hover-popover {
	background-color: var(--prime-bg-elevated);
	border: var(--prime-border-width) solid var(--prime-border-strong);
	border-radius: var(--prime-radius-m);
	box-shadow: var(--prime-shadow-l);
}

/* ── Notices ──────────────────────────────────────────────────────────── */

.notice {
	background-color: var(--prime-bg-elevated);
	color: var(--prime-text-normal);
	border: var(--prime-border-width) solid var(--prime-border-strong);
	border-left: 3px solid var(--prime-accent);
	border-radius: var(--prime-radius-m);
	box-shadow: var(--prime-shadow-m);
}

/* ── Tooltips ─────────────────────────────────────────────────────────── */

.tooltip {
	background-color: var(--prime-bg-elevated);
	color: var(--prime-text-normal);
	border: var(--prime-border-width) solid var(--prime-border-strong);
	border-radius: var(--prime-radius-s);
	box-shadow: var(--prime-shadow-m);
}

.tooltip .tooltip-arrow {
	border-bottom-color: var(--prime-bg-elevated);
}

/* ── UI · BUTTONS, INPUTS, TOGGLES, SETTINGS PANEL ─────────────────────── */

/* ── Buttons ──────────────────────────────────────────────────────────────
 * Clean-room interactive motion: a short colour + shadow response on hover
 * and a 1px press on active. Explicit property lists (PR-1). */

button:not(.clickable-icon),
.mod-cta,
input[type='button'],
input[type='submit'] {
	border-radius: var(--prime-button-radius);
	font-family: var(--prime-font-interface);
	font-weight: var(--prime-font-weight-medium);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard),
		box-shadow var(--prime-motion-fast) var(--prime-ease-standard),
		transform var(--prime-motion-superfast) var(--prime-ease-standard);
}

button:not(.clickable-icon):hover {
	background-color: var(--prime-bg-elevated);
	box-shadow: var(--prime-shadow-s);
}

button:not(.clickable-icon):active {
	transform: translateY(1px);
	box-shadow: none;
}

button.mod-cta {
	background-color: var(--prime-accent);
	color: var(--prime-text-on-accent);
}

button.mod-cta:hover {
	background-color: var(--prime-accent-hover);
}

button.mod-warning {
	background-color: var(--prime-color-red);
	color: var(--prime-text-on-accent);
}

/* ── Clickable icons ──────────────────────────────────────────────────── */

.clickable-icon {
	border-radius: var(--prime-radius-s);
	color: var(--prime-text-muted);
	transition: color var(--prime-motion-fast) var(--prime-ease-standard),
		background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.clickable-icon:hover {
	color: var(--prime-accent);
	background-color: var(--prime-surface-hover);
}

.clickable-icon.is-active {
	color: var(--prime-accent);
}

/* ── Inputs ───────────────────────────────────────────────────────────── */

input[type='text'],
input[type='search'],
input[type='email'],
input[type='password'],
input[type='number'],
input[type='date'],
textarea,
select,
.dropdown {
	background-color: var(--prime-bg-secondary);
	color: var(--prime-text-normal);
	border: var(--prime-border-width) solid var(--prime-border);
	border-radius: var(--prime-input-radius);
	font-family: var(--prime-font-interface);
	transition: border-color var(--prime-motion-fast) var(--prime-ease-standard),
		box-shadow var(--prime-motion-fast) var(--prime-ease-standard),
		background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

input[type='text']:hover,
input[type='search']:hover,
textarea:hover,
select:hover,
.dropdown:hover {
	border-color: var(--prime-border-hover);
}

input[type='text']:focus,
input[type='search']:focus,
input[type='email']:focus,
input[type='password']:focus,
input[type='number']:focus,
textarea:focus,
select:focus,
.dropdown:focus {
	border-color: var(--prime-border-focus);
	box-shadow: 0 0 0 3px color-mix(in srgb, var(--prime-accent) 18%, transparent);
	outline: none;
}

::placeholder {
	color: var(--prime-text-faint);
}

/* ── Toggle switches ──────────────────────────────────────────────────────
 * NOTE: .checkbox-container is Obsidian's SETTINGS TOGGLE, a <div>, not a
 * task checkbox. It is deliberately styled here rather than in
 * 60-checkboxes.css so the two never interfere — a distinction Obsidianite
 * blurred. */

.checkbox-container {
	background-color: var(--prime-bg-sunken);
	border: var(--prime-border-width) solid var(--prime-border);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard),
		border-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.checkbox-container:hover {
	border-color: var(--prime-border-hover);
}

.checkbox-container.is-enabled {
	background-color: var(--prime-accent);
	border-color: var(--prime-accent);
}

.checkbox-container::after {
	background-color: var(--prime-text-normal);
	transition: transform var(--prime-motion-fast) var(--prime-ease-overshoot),
		background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.checkbox-container.is-enabled::after {
	background-color: var(--prime-text-on-accent);
}

/* ── Sliders ──────────────────────────────────────────────────────────── */

input[type='range'] {
	background-color: transparent;
}

input[type='range']::-webkit-slider-runnable-track {
	background-color: var(--prime-bg-sunken);
	border-radius: var(--prime-radius-pill);
}

input[type='range']::-webkit-slider-thumb {
	background-color: var(--prime-accent);
	border: none;
	transition: transform var(--prime-motion-fast) var(--prime-ease-overshoot),
		box-shadow var(--prime-motion-fast) var(--prime-ease-standard);
}

input[type='range']::-webkit-slider-thumb:hover {
	transform: scale(1.15);
	box-shadow: 0 0 0 4px color-mix(in srgb, var(--prime-accent) 20%, transparent);
}

/* ── Settings panel ───────────────────────────────────────────────────── */

.vertical-tab-header,
.vertical-tab-content-container {
	background-color: var(--prime-bg-primary-alt);
}

.vertical-tab-nav-item {
	border-radius: var(--prime-radius-s);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

.vertical-tab-nav-item:hover {
	background-color: var(--prime-surface-hover);
	color: var(--prime-accent);
}

.vertical-tab-nav-item.is-active {
	background-color: var(--prime-surface-selected);
	color: var(--prime-accent);
}

.setting-item {
	border-top: var(--prime-border-width) solid var(--prime-border);
}

.setting-item-name {
	color: var(--prime-text-normal);
}

.setting-item-description {
	color: var(--prime-text-muted);
}

.setting-item-heading .setting-item-name {
	color: var(--prime-accent);
	font-weight: var(--prime-font-weight-semibold);
}

/* ── EDITOR · SHARED ───────────────────────────────────────────────────────
 *
 * Rules valid in BOTH Live Preview and Reading Mode.
 *
 * Obsidianite kept two divergent implementations for most components, which
 * is why its code blocks looked different in each mode (defect F-9). Prime
 * puts everything mode-agnostic here and keeps 41/42 for genuine mode
 * differences only.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-source-view,
.markdown-reading-view,
.markdown-preview-view {
	background-color: var(--prime-bg-primary);
}

/* Content width */
.markdown-source-view.mod-cm6 .cm-contentContainer,
.markdown-preview-sizer {
	max-width: var(--prime-content-width);
}

/* ── Images & media ───────────────────────────────────────────────────── */

.markdown-rendered img,
.markdown-rendered video,
.cm-s-obsidian img {
	border-radius: var(--prime-image-radius);
	max-width: 100%;
}

/* ── Footnotes ────────────────────────────────────────────────────────── */

.markdown-rendered sup.footnote-ref a,
.cm-s-obsidian .cm-footref {
	color: var(--prime-accent);
	text-decoration: none;
	font-weight: var(--prime-font-weight-medium);
}

.markdown-rendered .footnotes {
	border-top: var(--prime-border-width) solid var(--prime-border);
	color: var(--prime-text-muted);
	font-size: 0.9em;
}

/* ── Math ─────────────────────────────────────────────────────────────── */

.math,
mjx-container {
	color: var(--prime-text-normal);
}

.markdown-rendered mjx-container[display='true'] {
	padding: var(--prime-space-2) 0;
}

/* ── Frontmatter (raw YAML view) ──────────────────────────────────────── */

.cm-s-obsidian .cm-def,
.cm-s-obsidian .cm-atom {
	color: var(--prime-text-muted);
}

.cm-s-obsidian .cm-meta {
	color: var(--prime-accent);
}

.cm-s-obsidian .cm-string {
	color: var(--prime-accent-alt);
}

/* ── Horizontal scroll containers ─────────────────────────────────────── */

.markdown-rendered .block-language-dataview,
.markdown-rendered .table-wrapper {
	border-radius: var(--prime-radius-m);
}

/* ── EDITOR · LIVE PREVIEW / SOURCE (CM6 only) ─────────────────────────── */

.markdown-source-view.mod-cm6 .cm-scroller {
	font-family: var(--prime-font-text);
}

/* ── Cursor & active line ─────────────────────────────────────────────── */

.markdown-source-view.mod-cm6 .cm-cursor,
.cm-cursor-primary {
	border-left-color: var(--prime-accent);
	border-left-width: 2px;
}

.markdown-source-view.mod-cm6 .cm-active.cm-line {
	background-color: color-mix(in srgb, var(--prime-accent) 3%, transparent);
}

/* ── Formatting marks ─────────────────────────────────────────────────── */

.cm-s-obsidian .cm-formatting {
	color: var(--prime-text-faint);
	opacity: 0.5;
}

.cm-s-obsidian .cm-formatting-header {
	color: var(--prime-h-marker-color);
	opacity: 0.45;
}

.cm-s-obsidian .cm-formatting-list {
	color: var(--prime-list-marker-color);
}

.cm-s-obsidian .cm-formatting-quote {
	color: var(--prime-quote-border-color);
}

.cm-s-obsidian .cm-formatting-link,
.cm-s-obsidian .cm-formatting-link-string {
	color: var(--prime-text-faint);
	opacity: 0.4;
}

.cm-s-obsidian .cm-url {
	color: var(--prime-text-faint);
	opacity: 0.55;
	font-weight: var(--prime-font-weight);
}

.cm-s-obsidian .cm-formatting-image {
	color: var(--prime-accent);
	opacity: 0.7;
}

.cm-s-obsidian .cm-formatting-hashtag {
	color: var(--prime-text-faint);
}

/* ── Indent guides ────────────────────────────────────────────────────────
 * FIX F-14: Obsidianite declared `transition: opacity 500ms linear ease-in-out`
 * — two timing functions, so the whole declaration was invalid and dropped.
 * Indent guides never animated. Corrected to a single valid easing. */

.markdown-source-view.mod-cm6 .cm-indent::before {
	border-left-width: var(--prime-list-indent-width);
	border-color: var(--prime-list-indent-color);
	opacity: var(--prime-list-indent-opacity);
	transition: opacity var(--prime-motion-moderate) var(--prime-ease-standard);
}

.markdown-source-view.mod-cm6 .cm-active-indent::before {
	opacity: var(--prime-list-indent-opacity-active);
}

/* ── Fold & gutter ────────────────────────────────────────────────────── */

.markdown-source-view.mod-cm6 .cm-foldPlaceholder {
	background-color: var(--prime-surface-active);
	color: var(--prime-accent);
	border: none;
	border-radius: var(--prime-radius-xs);
}

.markdown-source-view.mod-cm6 .cm-gutters {
	background-color: transparent;
	color: var(--prime-text-faint);
	border: none;
}

.markdown-source-view.mod-cm6 .cm-lineNumbers .cm-gutterElement {
	color: var(--prime-text-faint);
}

/* ── Search / find in note ────────────────────────────────────────────── */

.cm-s-obsidian .obsidian-search-match-highlight,
.markdown-source-view.mod-cm6 .cm-searchMatch {
	background-color: var(--prime-search-bg);
	color: var(--prime-highlight-text);
	border-radius: var(--prime-radius-xs);
}

/* ── Embedded blocks ──────────────────────────────────────────────────── */

.markdown-source-view.mod-cm6 .cm-embed-block {
	border-radius: var(--prime-radius-m);
	padding: 0;
}

.markdown-source-view.mod-cm6 .cm-embed-block:hover {
	box-shadow: none;
}

/* ── EDITOR · READING MODE (.markdown-rendered) ────────────────────────────
 *
 * IMPORTANT SCOPING NOTE
 *
 * Prime targets `.markdown-rendered`, NOT `.markdown-preview-view`.
 *
 * Obsidianite used `.markdown-preview-view`, which is present ONLY on the
 * main reading pane. That left inline code, headings, tables and the rest
 * completely unstyled inside:
 *
 *     .markdown-embed-content .markdown-rendered   note embeds
 *     .hover-popover          .markdown-rendered   hover previews
 *     .canvas-node-content    .markdown-rendered   Canvas cards
 *     .content-preview        .markdown-rendered   Task List Kanban cards
 *                             .markdown-rendered   any plugin-rendered md
 *
 * `.markdown-rendered` is present in all of them. This single scoping change
 * is the secondary half of the Bug #2 fix and also resolves defect F-8
 * (headings unstyled in embeds/popovers). See docs/05 §4.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered {
	color: var(--prime-text-normal);
}

.markdown-rendered p {
	margin-block: 0.75em;
}

.markdown-rendered > *:first-child {
	margin-block-start: 0;
}

/* ── Unresolved internal links ────────────────────────────────────────── */

.markdown-rendered .internal-link.is-unresolved {
	color: var(--prime-link-unresolved-color);
}

/* ── Collapse indicators ──────────────────────────────────────────────────
 * Obsidianite forced `margin-left: -80px !important` here to clear the
 * gutter its fake checkbox occupied. That gutter no longer exists (Bug #1
 * fix), so the override — and its !important — are gone. */

.markdown-rendered .collapse-indicator {
	color: var(--prime-text-faint);
	transition: color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered .collapse-indicator:hover {
	color: var(--prime-accent);
}

/* ── Block reference highlight ────────────────────────────────────────── */

.markdown-rendered .is-flashing {
	background-color: var(--prime-search-bg);
	border-radius: var(--prime-radius-xs);
}

/* ── COMPONENT · HEADINGS ──────────────────────────────────────────────────
 *
 * Base implementation. Variant-specific decoration lives in
 * src/variants/71-variants-headings.css and only reassigns tokens.
 *
 * FIX F-8: targets .markdown-rendered (all reading contexts) rather than
 *          Obsidianite's .markdown-preview-section (main pane only).
 * FIX F-13: Obsidianite used `border-width: 35%`, which is invalid CSS and
 *          was silently discarded. Prime uses a real length token.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered :is(h1, h2, h3, h4, h5, h6),
.markdown-source-view.mod-cm6 .HyperMD-header {
	font-family: var(--prime-font-text);
	position: relative;
	margin-block-start: var(--prime-h-margin-top);
	margin-block-end: var(--prime-h-margin-bottom);
}

/* Live Preview headings keep the editor's own line box; only vertical
 * rhythm is applied so the two modes agree. Obsidianite applied 20px of
 * padding on all four sides here, causing a visible jump between modes. */
.markdown-source-view.mod-cm6 .HyperMD-header {
	padding-block: 0.15em;
}

/* ── Per-level sizing and colour ──────────────────────────────────────── */

.markdown-rendered h1,
.markdown-source-view.mod-cm6 .cm-header-1 {
	font-size: var(--prime-h1-size);
	font-weight: var(--prime-h1-weight);
	letter-spacing: var(--prime-h1-spacing);
	text-transform: var(--prime-h1-transform);
	color: var(--prime-h1-color);
}

.markdown-rendered h2,
.markdown-source-view.mod-cm6 .cm-header-2 {
	font-size: var(--prime-h2-size);
	font-weight: var(--prime-h2-weight);
	letter-spacing: var(--prime-h2-spacing);
	text-transform: var(--prime-h2-transform);
	color: var(--prime-h2-color);
}

.markdown-rendered h3,
.markdown-source-view.mod-cm6 .cm-header-3 {
	font-size: var(--prime-h3-size);
	font-weight: var(--prime-h3-weight);
	letter-spacing: var(--prime-h3-spacing);
	text-transform: var(--prime-h3-transform);
	color: var(--prime-h3-color);
}

.markdown-rendered h4,
.markdown-source-view.mod-cm6 .cm-header-4 {
	font-size: var(--prime-h4-size);
	font-weight: var(--prime-h4-weight);
	letter-spacing: var(--prime-h4-spacing);
	text-transform: var(--prime-h4-transform);
	color: var(--prime-h4-color);
}

.markdown-rendered h5,
.markdown-source-view.mod-cm6 .cm-header-5 {
	font-size: var(--prime-h5-size);
	font-weight: var(--prime-h5-weight);
	letter-spacing: var(--prime-h5-spacing);
	text-transform: var(--prime-h5-transform);
	color: var(--prime-h5-color);
}

.markdown-rendered h6,
.markdown-source-view.mod-cm6 .cm-header-6 {
	font-size: var(--prime-h6-size);
	font-weight: var(--prime-h6-weight);
	letter-spacing: var(--prime-h6-spacing);
	text-transform: var(--prime-h6-transform);
	color: var(--prime-h6-color);
}

/* ── Underline (variant-driven) ───────────────────────────────────────────
 * Rendered as a pseudo-element rather than border-image so that the
 * gradient can fade to `transparent` instead of to a hard-coded background
 * colour. Obsidianite baked #100e17 into its gradient, which broke whenever
 * the user changed the background. */

.markdown-rendered :is(h2, h3, h4, h5, h6)::after,
.markdown-source-view.mod-cm6 :is(.HyperMD-header-2, .HyperMD-header-3, .HyperMD-header-4, .HyperMD-header-5, .HyperMD-header-6)::after {
	content: '';
	display: var(--prime-h-underline-display);
	position: absolute;
	left: 0;
	right: 0;
	bottom: calc(-1 * var(--prime-h-underline-padding));
	height: var(--prime-h-underline-width);
	background-image: var(--prime-h-underline-image);
	background-color: transparent;
	pointer-events: none;
}

/* ── Accent bar (variant-driven) ──────────────────────────────────────── */

.markdown-rendered :is(h1, h2, h3, h4, h5, h6)::before {
	content: '';
	display: var(--prime-h-bar-display);
	position: absolute;
	left: calc(-1 * (var(--prime-h-bar-width) + var(--prime-space-3)));
	top: 0.15em;
	bottom: 0.15em;
	width: var(--prime-h-bar-width);
	border-radius: var(--prime-radius-pill);
	background-color: var(--prime-h-marker-color);
	pointer-events: none;
}

/* ── Headings in constrained contexts ─────────────────────────────────────
 * Embeds, popovers and Canvas cards are small; full heading margins would
 * dominate them. */

.markdown-embed .markdown-rendered :is(h1, h2, h3, h4, h5, h6),
.hover-popover .markdown-rendered :is(h1, h2, h3, h4, h5, h6),
.canvas-node-content .markdown-rendered :is(h1, h2, h3, h4, h5, h6) {
	margin-block-start: 0.6em;
	margin-block-end: 0.4em;
}

/* ── COMPONENT · DIVIDERS (hr) ─────────────────────────────────────────────
 *
 * Base implementation. All five visual styles live in
 * src/variants/70-variants-dividers.css and only reassign tokens.
 *
 * KNOWN LIMITATION (documented, see docs/08 §3.3): the decorative glyph
 * punches a hole in the rule using --prime-divider-glyph-bg. Inside a
 * callout or blockquote — which have a different background — that hole
 * will be the wrong colour. Prefer the Gradient or Minimal variant there.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered hr,
.markdown-source-view.mod-cm6 .cm-line hr {
	position: relative;
	height: 0;
	border: none;
	border-bottom: var(--prime-divider-thickness) solid var(--prime-divider-color);
	border-image-slice: 1;
	border-image-source: var(--prime-divider-image);
	margin-block: var(--prime-divider-margin);
	opacity: var(--prime-divider-opacity);
	background-color: transparent;
}

/* ── Decorative glyph ─────────────────────────────────────────────────── */

.markdown-rendered hr::after,
.markdown-source-view.mod-cm6 .cm-line hr::after {
	content: var(--prime-divider-glyph);
	display: var(--prime-divider-glyph-display);
	position: absolute;
	left: 50%;
	top: 0;
	transform: translate(-50%, -50%) rotate(var(--prime-divider-glyph-rotate));
	transform-origin: 50% 50%;
	padding: var(--prime-space-2);
	font-size: var(--prime-divider-glyph-size);
	line-height: 1;
	color: var(--prime-divider-glyph-color);
	background-color: var(--prime-divider-glyph-bg);
	pointer-events: none;
	transition: transform var(--prime-motion-moderate) var(--prime-ease-overshoot),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

/* Dividers in tight contexts get less breathing room */
.markdown-embed .markdown-rendered hr,
.hover-popover .markdown-rendered hr,
.canvas-node-content .markdown-rendered hr,
.callout .markdown-rendered hr {
	margin-block: 1.2em;
}

/* ── COMPONENT · LINKS ─────────────────────────────────────────────────────
 *
 * Obsidianite's signature "sweep" link (keeper K-4): rather than a
 * text-decoration underline, a small repeating background gradient is
 * anchored at the baseline and grows to fill the line box on hover.
 *
 * FIX F-12: Obsidianite line 696 read `cm-s-obsidian span.cm-link…` —
 *   missing the leading dot, so the entire rule was dead and editor-mode
 *   external links never received their accent. Corrected here.
 *
 * PERF: Obsidianite transitioned the `background` shorthand, forcing a full
 *   re-rasterisation. Prime transitions `background-size` only.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered :is(a.internal-link, a.external-link, a.tag),
.cm-s-obsidian :is(.cm-link, .cm-hmd-internal-link, .cm-url) {
	text-decoration: var(--prime-link-decoration);
}

/* ── The sweep ────────────────────────────────────────────────────────── */

.markdown-rendered a.internal-link,
.markdown-rendered a.external-link,
.cm-s-obsidian .cm-hmd-internal-link .cm-underline,
.cm-s-obsidian .cm-link:not(.cm-formatting-link) .cm-underline {
	color: var(--prime-link-color);
	background-repeat: no-repeat;
	background-position: 0 100%;
	background-size: 100% var(--prime-link-sweep-rest);
	text-decoration: none;
	border-radius: 2px;
	transition: background-size var(--prime-motion-moderate) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard),
		-webkit-text-fill-color var(--prime-motion-fast) var(--prime-ease-standard);
}

/* Internal links — accent */
.markdown-rendered a.internal-link,
.cm-s-obsidian .cm-hmd-internal-link .cm-underline {
	background-image: linear-gradient(
		to bottom,
		var(--prime-link-internal-accent) 0%,
		var(--prime-link-internal-accent) 100%
	);
}

/* External links — secondary accent */
.markdown-rendered a.external-link,
.cm-s-obsidian .cm-link:not(.cm-formatting-link) .cm-underline {
	background-image: linear-gradient(
		to bottom,
		var(--prime-link-external-accent) 0%,
		var(--prime-link-external-accent) 100%
	);
	padding: 0;
}

/* Unresolved links */
.markdown-rendered a.internal-link.is-unresolved {
	color: var(--prime-link-unresolved-color);
	background-image: linear-gradient(
		to bottom,
		var(--prime-link-unresolved-accent) 0%,
		var(--prime-link-unresolved-accent) 100%
	);
}

/* ── Hover: the sweep fills the line box ──────────────────────────────── */

.markdown-rendered a.internal-link:hover,
.markdown-rendered a.external-link:hover,
.cm-s-obsidian .cm-hmd-internal-link .cm-underline:hover,
.cm-s-obsidian .cm-link:not(.cm-formatting-link) .cm-underline:hover {
	background-size: 100% var(--prime-link-sweep-hover);
	color: var(--prime-link-hover-color);
	-webkit-text-fill-color: var(--prime-link-hover-color);
	text-decoration: none;
}

/* ── Generic anchors ──────────────────────────────────────────────────── */

.markdown-rendered a {
	color: var(--prime-link-color);
	text-decoration: none;
}

.markdown-rendered a:hover {
	text-decoration: none;
}

/* ── Link inside a heading inherits the heading colour ────────────────── */

.markdown-rendered :is(h1, h2, h3, h4, h5, h6) a {
	color: inherit;
	background-image: none;
	background-size: 100% var(--prime-link-sweep-rest);
}

.markdown-rendered :is(h1, h2, h3, h4, h5, h6) a:hover {
	color: var(--prime-accent-hover);
	-webkit-text-fill-color: var(--prime-accent-hover);
}

/* ── COMPONENT · EMPHASIS ──────────────────────────────────────────────────
 *
 * ╔══════════════════════════════════════════════════════════════════════╗
 * ║  BUG #2 — LAYER 3 OF 5  ·  GUARD THE GRADIENT AT ITS SOURCE          ║
 * ╚══════════════════════════════════════════════════════════════════════╝
 *
 * ROOT CAUSE RECAP (full analysis in docs/05)
 *
 *   Obsidianite.css:616-624 applied to BARE `strong`:
 *       -webkit-background-clip: text;
 *       -webkit-text-fill-color: transparent;
 *
 *   `-webkit-text-fill-color` INHERITS, and it overrides `color` for glyph
 *   fill. Any <code>, <kbd>, <mark>, <a> or tag nested inside a <strong>
 *   therefore inherited `transparent` and painted NO GLYPHS — while its own
 *   background still rendered, producing an empty coloured pill.
 *
 *   Obsidianite's inline-code rule set `color: … !important`, which cannot
 *   help: !important on `color` does not defeat an inherited
 *   -webkit-text-fill-color.
 *
 *   Evidence the original author hit this: Obsidianite.css:639-642 added
 *   `-webkit-text-fill-color: initial` for `strong kbd` — the exact escape
 *   hatch required — but never added the equivalent for `code`.
 *
 * PRIME'S APPROACH
 *
 *   Keep the gradient bold (it is an Obsidianite signature, keeper K-5) but
 *   make it structurally incapable of causing the bug:
 *
 *     Layer 3 (here)  :has() guard — a <strong> containing ANY nested inline
 *                     element does not receive the gradient at all, and
 *                     falls back to a solid colour.
 *     Layer 2 (here)  explicit fill reset on every inline child, for engines
 *                     or edge cases where the guard does not apply.
 *     Layer 1 (54)    inline code sets BOTH color and -webkit-text-fill-color.
 *     Layer 4 (80)    the gradient master switch removes the property entirely.
 *     Layer 5 (54)    no !important, so users can recolour freely.
 *
 *   Layers 1-3 are each independently sufficient. Defence in depth is
 *   warranted because this property's inheritance is easy to reintroduce.
 *
 * PERF NOTE (I-10): :has() is used here only on `strong`/`.cm-strong`, which
 *   are low-frequency and stable. It is never used on .cm-line.
 * ──────────────────────────────────────────────────────────────────────── */

/* ── BOLD · solid baseline ────────────────────────────────────────────────
 * Declared FIRST and unconditionally, so that whenever the gradient is
 * absent — guarded, toggled off, or unsupported — bold text is already
 * correctly coloured. Nothing can end up invisible. */

.markdown-rendered strong,
.cm-s-obsidian .cm-strong {
	color: var(--prime-bold-color);
	font-weight: var(--prime-bold-weight);
}

/* ── BOLD · gradient, guarded (LAYER 3) ──────────────────────────────────
 * The :has() guard is the root-cause fix. A <strong> that contains a nested
 * inline element simply never gets the clipping properties. */

body.prime-gradients-on
	:is(.markdown-rendered strong, .cm-s-obsidian .cm-strong):not(
		:has(code, kbd, mark, a, .tag, .math, img, svg)
	) {
	background-image: var(--prime-bold-gradient);
	-webkit-background-clip: text;
	background-clip: text;
	-webkit-text-fill-color: transparent;
}

/* ── LAYER 2 · explicit fill reset on every inline child ─────────────────
 * Generalises Obsidianite's <kbd>-only escape hatch to the full set of
 * inline elements that can legally nest inside emphasis. */

:is(.markdown-rendered strong, .cm-s-obsidian .cm-strong)
	:is(code, kbd, mark, a, .tag, .math, .cm-inline-code, .cm-hashtag) {
	-webkit-text-fill-color: initial;
	-webkit-background-clip: initial;
	background-clip: initial;
	background-image: none;
}

/* Bold text selection must remain legible under a transparent fill */
.markdown-rendered strong::selection,
.cm-s-obsidian .cm-strong::selection {
	-webkit-text-fill-color: var(--prime-text-normal);
	background-color: var(--prime-selection-bg);
}

/* ── ITALIC ───────────────────────────────────────────────────────────── */

.markdown-rendered em,
.cm-s-obsidian .cm-em {
	color: var(--prime-italic-color);
	font-style: var(--prime-italic-style);
}

/* ── BOLD ITALIC ──────────────────────────────────────────────────────────
 * Explicitly solid. Gradient-clipping nested emphasis is where the original
 * bug was most visible, so Prime does not attempt it. */

.markdown-rendered strong em,
.markdown-rendered em strong,
.cm-s-obsidian .cm-strong.cm-em {
	color: var(--prime-italic-color);
	-webkit-text-fill-color: initial;
	background-image: none;
	font-weight: var(--prime-bold-weight);
	font-style: var(--prime-italic-style);
}

/* ── HIGHLIGHT ────────────────────────────────────────────────────────────
 * Must reset the inherited fill too — ==highlight== inside **bold** was
 * another casualty of the original rule. */

.markdown-rendered mark,
.cm-s-obsidian .cm-highlight {
	color: var(--prime-highlight-text);
	-webkit-text-fill-color: var(--prime-highlight-text);
	background-color: var(--prime-highlight-bg);
	background-image: none;
	-webkit-background-clip: initial;
	background-clip: initial;
	border-radius: var(--prime-highlight-radius);
	padding: var(--prime-highlight-padding);
}

/* ── STRIKETHROUGH ────────────────────────────────────────────────────── */

.markdown-rendered del,
.markdown-rendered s,
.cm-s-obsidian .cm-strikethrough {
	color: var(--prime-strike-color);
	-webkit-text-fill-color: var(--prime-strike-color);
	text-decoration-color: var(--prime-strike-color);
}

/* ── Live Preview formatting-mark sizing ──────────────────────────────────
 * Obsidianite shrank the `*` markers with display:inline-flex, which caused
 * baseline drift. A plain opacity reduction reads the same and does not
 * disturb the line box. */

.cm-s-obsidian .cm-formatting-em,
.cm-s-obsidian .cm-formatting-strong,
.cm-s-obsidian .cm-formatting-highlight,
.cm-s-obsidian .cm-formatting-strikethrough {
	-webkit-text-fill-color: initial;
	background-image: none;
	color: var(--prime-text-faint);
	opacity: 0.5;
}

/* ── COMPONENT · INLINE CODE ───────────────────────────────────────────────
 *
 * ╔══════════════════════════════════════════════════════════════════════╗
 * ║  BUG #2 — LAYERS 1, 2 AND 5  ·  INLINE CODE INVISIBLE IN READING     ║
 * ╚══════════════════════════════════════════════════════════════════════╝
 *
 * TWO INDEPENDENT DEFECTS IN OBSIDIANITE, BOTH FIXED HERE.
 *
 * ── PRIMARY CAUSE · inherited -webkit-text-fill-color ───────────────────
 *
 *   Obsidianite.css:619   strong { -webkit-text-fill-color: transparent }
 *   Obsidianite.css:1098  code   { color: rgba(...) !important }
 *
 *   -webkit-text-fill-color INHERITS and takes precedence over `color` for
 *   glyph fill. `code` inside `strong` therefore painted transparent glyphs
 *   on a visible background — an empty pill. `!important` on `color` was
 *   powerless because the winning property was a different one.
 *
 *   Layer 1 (below) sets BOTH `color` and `-webkit-text-fill-color`, which
 *   neutralises the inheritance directly and unconditionally.
 *
 * ── SECONDARY CAUSE · selector scope too narrow ─────────────────────────
 *
 *   Obsidianite.css:1092  .markdown-preview-view code
 *
 *   `.markdown-preview-view` exists only on the main reading pane. Inline
 *   code was therefore COMPLETELY UNSTYLED in note embeds, hover popovers,
 *   Canvas cards, and any plugin-rendered markdown (including Task List
 *   Kanban card previews).
 *
 *   Prime targets `.markdown-rendered`, which is present in every one of
 *   those contexts, plus `.cm-inline-code` for Live Preview.
 *
 * ── LAYER 5 · no !important ─────────────────────────────────────────────
 *
 *   Obsidianite's `!important` was almost certainly added while chasing this
 *   very bug, in the mistaken belief that specificity was the problem. It is
 *   unnecessary once the fill colour is set correctly, and it actively
 *   blocked Style Settings customisation. It is gone.
 *
 * Full analysis: docs/05-bug-02-inline-code-reading-mode.md
 * ──────────────────────────────────────────────────────────────────────── */

/* ══ LAYER 1 · the canonical inline-code rule ═══════════════════════════
 *
 * `:not(pre > code)` excludes fenced-block content using the child
 * combinator — tighter and marginally cheaper than a descendant `:not()`.
 *
 * The selector list deliberately covers every context Obsidian renders
 * markdown into. Each entry is load-bearing:
 *
 *   .markdown-rendered code       reading, embeds, popovers, Canvas, plugins
 *   .cm-inline-code               Live Preview
 *   .cm-s-obsidian code           source-mode fallback
 */

.markdown-rendered code:not(pre > code),
.cm-s-obsidian .cm-inline-code:not(.cm-formatting):not(.cm-hmd-indented-code),
.cm-s-obsidian code:not(pre > code) {
	/* Both properties. `color` alone is defeated by inherited fill. */
	color: var(--prime-inline-code-color);
	-webkit-text-fill-color: var(--prime-inline-code-color);

	/* Neutralise any inherited gradient clipping from an ancestor. */
	background-image: none;
	-webkit-background-clip: initial;
	background-clip: initial;

	background-color: var(--prime-inline-code-bg);
	border: var(--prime-inline-code-border-width) solid var(--prime-inline-code-border);
	border-radius: var(--prime-inline-code-radius);
	padding: var(--prime-inline-code-padding);

	font-family: var(--prime-font-monospace);
	font-size: var(--prime-inline-code-size);
	font-weight: var(--prime-inline-code-weight);
	font-style: normal;

	overflow-wrap: break-word;
	word-break: break-word;
	white-space: pre-wrap;
}

/* ══ LAYER 2 · defensive resets in every emphasis context ═══════════════
 *
 * Layer 1 already wins in the common case. These exist because
 * -webkit-text-fill-color inheritance can arrive from an ancestor Prime
 * does not control (a snippet, another plugin, a future rule), and because
 * the failure mode — silently invisible text — is severe enough to warrant
 * belt and braces.
 */

:is(strong, em, del, s, mark, a, h1, h2, h3, h4, h5, h6)
	:is(code, .cm-inline-code) {
	-webkit-text-fill-color: var(--prime-inline-code-color);
	background-image: none;
	-webkit-background-clip: initial;
	background-clip: initial;
}

/* Inline code inside a heading tracks the heading's scale, not the body's */
.markdown-rendered :is(h1, h2, h3, h4, h5, h6) code:not(pre > code) {
	font-size: 0.9em;
}

/* ── Context tinting ──────────────────────────────────────────────────── */

/* Inside a blockquote or callout the standard translucent background can
 * disappear against the container's own tint. */
.markdown-rendered :is(blockquote, .callout) code:not(pre > code),
.cm-s-obsidian .cm-quote.cm-inline-code {
	color: var(--prime-inline-code-color);
	-webkit-text-fill-color: var(--prime-inline-code-color);
	background-color: color-mix(in srgb, var(--prime-accent) 14%, transparent);
}

/* Inline code inside a link should not fight the link's sweep */
.markdown-rendered a code:not(pre > code) {
	background-color: color-mix(in srgb, var(--prime-accent) 14%, transparent);
}

/* Inline code inside a table cell */
.markdown-rendered table code:not(pre > code) {
	white-space: nowrap;
}

/* ── Live Preview formatting backticks ────────────────────────────────────
 * The backtick delimiters themselves. Obsidianite forced these to
 * `display: inline-flex; min-width: .55rem`, which disturbed the line box.
 * A simple de-emphasis is sufficient and does not affect layout. */

.cm-s-obsidian .cm-inline-code.cm-formatting-code {
	color: var(--prime-text-faint);
	-webkit-text-fill-color: var(--prime-text-faint);
	background-color: transparent;
	background-image: none;
	padding: 0;
	border: none;
	opacity: 0.5;
}

/* Active line: do not double up padding on the delimiters */
.cm-s-obsidian .cm-active .cm-inline-code.cm-formatting-code {
	opacity: 0.7;
}

/* ── COMPONENT · CODE BLOCKS ───────────────────────────────────────────────
 *
 * FIX F-9: Obsidianite had two divergent implementations — Live Preview used
 *   #191621 while Reading Mode used the vendored Dracula's rgb(40,41,54).
 *   The same code block looked different in each mode. Prime drives both
 *   from a single --prime-code-bg token.
 *
 * FIX (upstream issue #44): Obsidianite painted a fake rounded top corner
 *   with an absolutely-positioned ::before on .HyperMD-codeblock-begin-bg.
 *   That rectangle covered the first line of code in Live Preview. Prime
 *   uses border-radius on the real container; the pseudo-element is gone.
 *
 * FIX F-10: the `pre[class$='javascript']:before` language-label trick never
 *   matched modern Obsidian output ([class$=] tests the END of the whole
 *   class attribute, and Obsidian emits e.g. "language-js is-loaded").
 *   Removed. Language labels are a documented future milestone; Prime styles
 *   Obsidian's native .code-block-flair instead.
 *
 * DECISION G-4: the vendored Prism-Dracula block is NOT carried over. Syntax
 *   colours are re-derived from the Prime palette in 56-syntax.css.
 * ──────────────────────────────────────────────────────────────────────── */

/* ── Reading Mode ─────────────────────────────────────────────────────── */

.markdown-rendered pre {
	position: relative;
	background-color: var(--prime-code-bg);
	border: var(--prime-code-border-width) solid var(--prime-code-border);
	border-radius: var(--prime-code-radius);
	padding: var(--prime-code-padding);
	margin-block: 1em;
	overflow: auto;
}

.markdown-rendered pre > code {
	background-color: transparent;
	color: var(--prime-code-color);
	font-family: var(--prime-font-monospace);
	font-size: var(--prime-code-size);
	line-height: var(--prime-code-line-height);
	padding: 0;
	border: none;
	border-radius: 0;
	/* Reset any inherited gradient clipping (Bug #2 defence). */
	-webkit-text-fill-color: initial;
	background-image: none;
	-webkit-background-clip: initial;
	background-clip: initial;
}

/* ── Live Preview ─────────────────────────────────────────────────────── */

.markdown-source-view.mod-cm6 .HyperMD-codeblock {
	background-color: var(--prime-code-bg);
	color: var(--prime-code-color);
	font-family: var(--prime-font-monospace);
	font-size: var(--prime-code-size);
	line-height: var(--prime-code-line-height);
	padding-inline: var(--prime-code-padding);
	border-left: var(--prime-code-border-width) solid var(--prime-code-border);
	border-right: var(--prime-code-border-width) solid var(--prime-code-border);
}

.markdown-source-view.mod-cm6 .HyperMD-codeblock-begin {
	border-top: var(--prime-code-border-width) solid var(--prime-code-border);
	border-top-left-radius: var(--prime-code-radius);
	border-top-right-radius: var(--prime-code-radius);
	padding-top: 0.4em;
}

.markdown-source-view.mod-cm6 .HyperMD-codeblock-end {
	border-bottom: var(--prime-code-border-width) solid var(--prime-code-border);
	border-bottom-left-radius: var(--prime-code-radius);
	border-bottom-right-radius: var(--prime-code-radius);
	padding-bottom: 0.4em;
}

/* The fence delimiters themselves */
.cm-s-obsidian .cm-formatting-code-block {
	color: var(--prime-text-faint);
	opacity: 0.55;
}

/* ── Language flair ───────────────────────────────────────────────────────
 * Obsidian's own native language indicator. Prime styles it; it does not
 * attempt to synthesise labels. */

.markdown-source-view.mod-cm6 .code-block-flair,
.markdown-rendered .code-block-flair {
	color: var(--prime-code-flair-color);
	background-color: var(--prime-code-flair-bg);
	border: var(--prime-border-width) solid var(--prime-border);
	border-radius: var(--prime-code-flair-radius);
	font-family: var(--prime-font-interface);
	font-size: var(--prime-code-flair-size);
	font-weight: var(--prime-font-weight-semibold);
	text-transform: uppercase;
	letter-spacing: 0.04em;
	padding: 0.15em 0.7em;
	opacity: 0.85;
	transition: opacity var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-source-view.mod-cm6 .code-block-flair:hover,
.markdown-rendered .code-block-flair:hover {
	opacity: 1;
}

body.prime-no-code-flair .code-block-flair {
	display: none;
}

/* ── Copy button ──────────────────────────────────────────────────────────
 * Styled only — Obsidian provides the button. Advanced copy-button features
 * are a documented future milestone. */

.markdown-rendered button.copy-code-button {
	color: var(--prime-text-muted);
	background-color: var(--prime-bg-primary-alt);
	border: var(--prime-border-width) solid var(--prime-border);
	border-radius: var(--prime-radius-s);
	font-size: 0.72em;
	opacity: 0;
	transition: opacity var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered pre:hover button.copy-code-button {
	opacity: 1;
}

.markdown-rendered button.copy-code-button:hover {
	color: var(--prime-accent);
}

/* ── Indented (non-fenced) code ───────────────────────────────────────── */

.cm-s-obsidian .cm-hmd-indented-code {
	color: var(--prime-code-color);
	font-family: var(--prime-font-monospace);
}

/* ── COMPONENT · SYNTAX HIGHLIGHTING ───────────────────────────────────────
 *
 * DECISION G-4 — the vendored Prism-Dracula theme (Obsidianite lines
 * 1163-1481, ~320 lines, © Gustavo Costa / Jon Leopard, MIT) is NOT carried
 * into Obsidian Prime.
 *
 * Reasons:
 *   1. No documented dependency required it.
 *   2. Its palette (Dracula purple/pink/green) clashes with Obsidianite's
 *      cyan/magenta identity — it was visibly a foreign body.
 *   3. It hard-coded rgb(40,41,54) as the code background, which is why
 *      Reading Mode and Live Preview disagreed (defect F-9).
 *   4. It introduced a third-party copyright holder into the licence surface
 *      for no benefit.
 *
 * Instead, ONE palette (--prime-syntax-*) drives BOTH highlighters:
 *   - CodeMirror 6 `.cm-*` classes            → Live Preview
 *   - Obsidian's bundled Prism `.token.*`     → Reading Mode
 *
 * This is why syntax colours now match across modes, and why a user changing
 * one syntax colour in Style Settings changes it in both.
 * ──────────────────────────────────────────────────────────────────────── */

/* ══ CodeMirror 6 · Live Preview ════════════════════════════════════════ */

.cm-s-obsidian .HyperMD-codeblock .cm-comment,
.cm-s-obsidian .cm-hmd-codeblock.cm-comment {
	color: var(--prime-syntax-comment);
	font-style: italic;
}

.cm-s-obsidian .HyperMD-codeblock .cm-keyword,
.cm-s-obsidian .cm-hmd-codeblock.cm-keyword {
	color: var(--prime-syntax-keyword);
}

.cm-s-obsidian .HyperMD-codeblock .cm-string,
.cm-s-obsidian .HyperMD-codeblock .cm-string-2,
.cm-s-obsidian .cm-hmd-codeblock.cm-string {
	color: var(--prime-syntax-string);
}

.cm-s-obsidian .HyperMD-codeblock .cm-number,
.cm-s-obsidian .cm-hmd-codeblock.cm-number {
	color: var(--prime-syntax-number);
}

.cm-s-obsidian .HyperMD-codeblock .cm-def,
.cm-s-obsidian .cm-hmd-codeblock.cm-def {
	color: var(--prime-syntax-function);
}

.cm-s-obsidian .HyperMD-codeblock .cm-variable,
.cm-s-obsidian .cm-hmd-codeblock.cm-variable {
	color: var(--prime-syntax-variable);
}

.cm-s-obsidian .HyperMD-codeblock .cm-variable-2,
.cm-s-obsidian .HyperMD-codeblock .cm-property {
	color: var(--prime-syntax-property);
}

.cm-s-obsidian .HyperMD-codeblock .cm-variable-3,
.cm-s-obsidian .HyperMD-codeblock .cm-type {
	color: var(--prime-syntax-type);
}

.cm-s-obsidian .HyperMD-codeblock .cm-operator {
	color: var(--prime-syntax-operator);
}

.cm-s-obsidian .HyperMD-codeblock .cm-punctuation,
.cm-s-obsidian .HyperMD-codeblock .cm-bracket {
	color: var(--prime-syntax-punctuation);
}

.cm-s-obsidian .HyperMD-codeblock .cm-atom {
	color: var(--prime-syntax-constant);
}

.cm-s-obsidian .HyperMD-codeblock .cm-tag {
	color: var(--prime-syntax-tag);
}

.cm-s-obsidian .HyperMD-codeblock .cm-attribute,
.cm-s-obsidian .HyperMD-codeblock .cm-qualifier {
	color: var(--prime-syntax-attribute);
}

.cm-s-obsidian .HyperMD-codeblock .cm-builtin {
	color: var(--prime-syntax-builtin);
}

.cm-s-obsidian .HyperMD-codeblock .cm-meta {
	color: var(--prime-syntax-comment);
}

/* ══ Prism · Reading Mode ═══════════════════════════════════════════════ */

.markdown-rendered .token.comment,
.markdown-rendered .token.prolog,
.markdown-rendered .token.cdata {
	color: var(--prime-syntax-comment);
	font-style: italic;
}

.markdown-rendered .token.keyword,
.markdown-rendered .token.important,
.markdown-rendered .token.atrule {
	color: var(--prime-syntax-keyword);
}

.markdown-rendered .token.string,
.markdown-rendered .token.char,
.markdown-rendered .token.attr-value,
.markdown-rendered .token.inserted {
	color: var(--prime-syntax-string);
}

.markdown-rendered .token.number,
.markdown-rendered .token.boolean {
	color: var(--prime-syntax-number);
}

.markdown-rendered .token.function,
.markdown-rendered .token.class-name {
	color: var(--prime-syntax-function);
}

.markdown-rendered .token.variable,
.markdown-rendered .token.symbol {
	color: var(--prime-syntax-variable);
}

.markdown-rendered .token.property,
.markdown-rendered .token.attr-name {
	color: var(--prime-syntax-property);
}

.markdown-rendered .token.operator,
.markdown-rendered .token.entity,
.markdown-rendered .token.url {
	color: var(--prime-syntax-operator);
}

.markdown-rendered .token.punctuation {
	color: var(--prime-syntax-punctuation);
}

.markdown-rendered .token.constant {
	color: var(--prime-syntax-constant);
}

.markdown-rendered .token.tag,
.markdown-rendered .token.deleted {
	color: var(--prime-syntax-tag);
}

.markdown-rendered .token.selector {
	color: var(--prime-syntax-type);
}

.markdown-rendered .token.builtin,
.markdown-rendered .token.namespace {
	color: var(--prime-syntax-builtin);
}

.markdown-rendered .token.regex {
	color: var(--prime-syntax-regex);
}

.markdown-rendered .token.bold {
	font-weight: var(--prime-bold-weight);
}

.markdown-rendered .token.italic {
	font-style: italic;
}

/* ── COMPONENT · BLOCKQUOTES ───────────────────────────────────────────────
 *
 * FIX F-5 / conflict 4.7: Obsidian renders CALLOUTS as
 * `<blockquote data-callout="...">`. Obsidianite had no callout rules at
 * all, so every callout inherited the blockquote's left border, gradient
 * bars and `!!` glyph — fighting the callout's own icon and title bar.
 *
 * Every rule here is scoped `:not(.callout)`. Callouts are handled properly
 * in 58-callouts.css.
 *
 * ACCESSIBILITY: Obsidianite injected a literal `!!` via `content`, which
 * screen readers announce. Prime's optional glyph uses the `content: X / ""`
 * alt-text syntax so assistive technology skips it, and it is OFF by default.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered blockquote:not(.callout),
.markdown-source-view.mod-cm6 .HyperMD-quote {
	position: relative;
	color: var(--prime-quote-color);
	background-color: var(--prime-quote-bg);
	font-style: var(--prime-quote-style);
	border: none;
	border-left: var(--prime-quote-border-width) solid var(--prime-quote-border-color);
	border-radius: 0 var(--prime-quote-radius) var(--prime-quote-radius) 0;
	margin-inline-start: 0;
	padding: var(--prime-quote-padding);
}

.markdown-rendered blockquote:not(.callout) {
	margin-block: var(--prime-quote-margin);
}

/* ── Decorative gradient bars (Obsidianite keeper K-6) ───────────────────
 * A short bright bar at the top and a shorter one at the bottom. Both fade
 * to `transparent` rather than to a hard-coded background colour, so they
 * survive a user changing the theme background. */

.markdown-rendered blockquote:not(.callout)::before {
	content: '';
	display: var(--prime-quote-bar-display);
	position: absolute;
	top: 0;
	left: 0;
	height: 2px;
	width: 55%;
	background-image: linear-gradient(
		90deg,
		var(--prime-quote-border-color),
		transparent
	);
	pointer-events: none;
}

.markdown-rendered blockquote:not(.callout)::after {
	content: '';
	display: var(--prime-quote-bar-display);
	position: absolute;
	bottom: 0;
	left: 0;
	height: 2px;
	width: 25%;
	background-image: linear-gradient(
		90deg,
		var(--prime-quote-border-color),
		transparent
	);
	pointer-events: none;
}

/* ── Optional quote glyph (off by default) ────────────────────────────────
 * `content: X / ""` supplies empty alt text, so screen readers skip it. */

.markdown-rendered blockquote:not(.callout) > p:first-of-type::before {
	content: var(--prime-quote-glyph) / '';
	display: var(--prime-quote-glyph-display);
	position: absolute;
	top: 0.1em;
	left: 0.55em;
	font-size: 1.6em;
	line-height: 1;
	font-style: italic;
	font-weight: var(--prime-font-weight-bold);
	color: var(--prime-quote-glyph-color);
	opacity: 0.5;
	pointer-events: none;
}

.markdown-rendered blockquote:not(.callout) > p {
	margin-block: 0.4em;
}

.markdown-rendered blockquote:not(.callout) > *:first-child {
	margin-block-start: 0;
}

.markdown-rendered blockquote:not(.callout) > *:last-child {
	margin-block-end: 0;
}

/* Nested quotes de-emphasise rather than compound decoration */
.markdown-rendered blockquote:not(.callout) blockquote:not(.callout) {
	background-color: transparent;
	border-left-color: var(--prime-accent-muted);
}

.markdown-rendered blockquote:not(.callout) blockquote:not(.callout)::before,
.markdown-rendered blockquote:not(.callout) blockquote:not(.callout)::after {
	display: none;
}

/* Live Preview: only the first quote line carries the top bar */
.markdown-source-view.mod-cm6 .HyperMD-quote + .HyperMD-quote::before {
	display: none;
}

/* ── COMPONENT · CALLOUTS ──────────────────────────────────────────────────
 *
 * NEW IN PRIME. Obsidianite had zero callout rules (defect F-5), so callouts
 * inherited blockquote styling and looked broken.
 *
 * Implementation uses color-mix() against the editor background rather than
 * pre-computed alpha variables, so a single --callout-color per type drives
 * the background, the title bar and the accent edge coherently — in both
 * light and dark mode, without duplicated tokens.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered .callout,
.markdown-source-view.mod-cm6 .callout {
	--callout-radius: var(--prime-callout-radius);
	position: relative;
	overflow: hidden;
	padding: 0;
	margin-block: 1em;
	border: var(--prime-callout-border-width) solid
		color-mix(in srgb, rgb(var(--callout-color)) 25%, transparent);
	border-radius: var(--prime-callout-radius);
	background-color: color-mix(
		in srgb,
		rgb(var(--callout-color)) var(--prime-callout-bg-opacity),
		var(--prime-bg-primary)
	);
	mix-blend-mode: normal;
}

/* Left accent edge */
.markdown-rendered .callout::before,
.markdown-source-view.mod-cm6 .callout::before {
	content: '';
	position: absolute;
	inset: 0 auto 0 0;
	width: var(--prime-callout-accent-width);
	background-color: rgb(var(--callout-color));
	pointer-events: none;
}

/* ── Title ────────────────────────────────────────────────────────────── */

.markdown-rendered .callout-title,
.markdown-source-view.mod-cm6 .callout-title {
	padding: var(--prime-callout-title-padding);
	padding-inline-start: calc(var(--prime-callout-accent-width) + var(--prime-space-3));
	background-color: color-mix(
		in srgb,
		rgb(var(--callout-color)) var(--prime-callout-title-bg-opacity),
		transparent
	);
	font-size: var(--prime-callout-title-size);
	font-weight: var(--prime-callout-title-weight);
	color: var(--prime-callout-title-color);
	gap: var(--prime-space-2);
	align-items: center;
}

.markdown-rendered .callout-icon,
.markdown-source-view.mod-cm6 .callout-icon {
	display: var(--prime-callout-icon-display);
	color: rgb(var(--callout-color));
	align-items: center;
}

.markdown-rendered .callout-title-inner {
	color: var(--prime-callout-title-color);
}

/* ── Content ──────────────────────────────────────────────────────────── */

.markdown-rendered .callout-content,
.markdown-source-view.mod-cm6 .callout-content {
	padding: var(--prime-callout-padding);
	padding-inline-start: calc(var(--prime-callout-accent-width) + var(--prime-space-3));
}

.markdown-rendered .callout-content > *:first-child {
	margin-block-start: 0;
}

.markdown-rendered .callout-content > *:last-child {
	margin-block-end: 0;
}

/* ── Collapsible ──────────────────────────────────────────────────────── */

.markdown-rendered .callout.is-collapsible .callout-title {
	cursor: var(--prime-cursor);
}

.markdown-rendered .callout.is-collapsible.is-collapsed .callout-title {
	border-radius: var(--prime-callout-radius);
}

.markdown-rendered .callout-fold {
	color: rgb(var(--callout-color));
	opacity: 0.7;
	transition: transform var(--prime-motion-fast) var(--prime-ease-standard),
		opacity var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered .callout-title:hover .callout-fold {
	opacity: 1;
}

/* ── Type colours ─────────────────────────────────────────────────────────
 * Obsidian expects --callout-color as a bare "r, g, b" triplet.
 * Derived here from Prime's semantic colour set. */

.theme-dark,
.theme-light {
	--callout-default: var(--prime-accent-rgb);
	--callout-info: var(--prime-accent-rgb);
	--callout-summary: var(--prime-accent-rgb);
	--callout-tip: 45, 206, 168;
	--callout-success: 63, 191, 127;
	--callout-question: 173, 138, 245;
	--callout-warning: 240, 168, 40;
	--callout-failure: 233, 84, 84;
	--callout-danger: 233, 84, 84;
	--callout-bug: 233, 84, 84;
	--callout-example: 173, 138, 245;
	--callout-quote: 150, 150, 160;
	--callout-important: var(--prime-accent-alt-rgb);
	--callout-todo: var(--prime-accent-rgb);
	--callout-abstract: 45, 206, 168;
	--callout-note: var(--prime-accent-rgb);
}

/* ── Nested content harmony ───────────────────────────────────────────── */

.markdown-rendered .callout blockquote:not(.callout) {
	background-color: transparent;
}

.markdown-rendered .callout pre {
	background-color: color-mix(in srgb, var(--prime-bg-sunken) 60%, transparent);
}

/* ── COMPONENT · LISTS ─────────────────────────────────────────────────────
 *
 * NOTE ON WHAT IS *NOT* HERE
 *
 * Obsidianite carried three layout hacks in this area, all of which existed
 * only to make room for its fake checkbox:
 *
 *     .markdown-preview-view ul > li.task-list-item { text-indent: -3em }
 *     .contains-task-list .task-list-item { padding-left: 30px }
 *     .markdown-preview-view .list-collapse-indicator { margin-left: -80px !important }
 *
 * All three are gone. Prime's checkbox is the input itself and occupies its
 * own inline box in normal flow, so no gutter needs reserving and no negative
 * offsets need compensating. Task lists now use Obsidian's native list
 * geometry, which is also why they survive being re-parented by plugins.
 *
 * See 60-checkboxes.css and docs/04.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered ul,
.markdown-rendered ol {
	padding-inline-start: 1.6em;
}

.markdown-rendered li {
	margin-block: var(--prime-list-spacing);
}

.markdown-rendered li > p {
	margin-block: 0.2em;
}

/* ── Markers ──────────────────────────────────────────────────────────── */

.markdown-rendered ul > li::marker {
	color: var(--prime-list-marker-color);
	font-weight: var(--prime-list-marker-weight);
}

.markdown-rendered ol > li::marker {
	color: var(--prime-list-number-color);
	font-weight: var(--prime-list-marker-weight);
}

/* Live Preview bullet */
.markdown-source-view.mod-cm6 .list-bullet::after {
	background-color: var(--prime-list-marker-color);
}

.cm-s-obsidian .cm-formatting-list-ol {
	color: var(--prime-list-number-color);
	font-weight: var(--prime-list-marker-weight);
}

/* ── Indent guides (Reading Mode) ─────────────────────────────────────── */

.markdown-rendered .list-collapse-indicator {
	color: var(--prime-text-faint);
	transition: color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered .list-collapse-indicator:hover {
	color: var(--prime-accent);
}

/* ── Definition lists ─────────────────────────────────────────────────── */

.markdown-rendered dt {
	color: var(--prime-accent);
	font-weight: var(--prime-font-weight-semibold);
}

.markdown-rendered dd {
	color: var(--prime-text-muted);
}

/* ── COMPONENT · CHECKBOXES ────────────────────────────────────────────────
 *
 * ╔══════════════════════════════════════════════════════════════════════╗
 * ║  BUG #1 — ROOT-CAUSE FIX  ·  TASK LIST KANBAN CHECKBOX RENDERING     ║
 * ╚══════════════════════════════════════════════════════════════════════╝
 *
 * ── WHY OBSIDIANITE'S IMPLEMENTATION WORKED FOR NORMAL TASK LISTS ───────
 *
 *   Obsidianite hid the real input and painted a substitute on the PARENT:
 *
 *       .contains-task-list .task-list-item input[type=checkbox] { opacity: 0 }
 *       .contains-task-list .task-list-item::before  { position:absolute; left:-25px }
 *       .contains-task-list .task-list-item::after   { the tick }
 *       .contains-task-list .task-list-item          { padding-left: 30px }
 *
 *   Obsidian's own markdown renderer emits exactly the DOM this assumes:
 *
 *       <ul class="contains-task-list">          ← required ancestor  ✔
 *         <li class="task-list-item">            ← positioned block box ✔
 *           <input type="checkbox">              ← hidden hit target
 *
 *   Both preconditions hold, the 30px gutter exists, and the substitute
 *   renders neatly inside it. For canonical markdown lists it worked well.
 *
 * ── WHY IT FAILED FOR TASK LIST KANBAN ──────────────────────────────────
 *
 *   TaskStatusMarker.svelte (plugin main.js:15336-15342) emits:
 *
 *       <span class="task-status-marker …">      ← NOT a <ul>, NOT .contains-task-list
 *         <span class="task-list-item HyperMD-task-line" data-task="x">
 *           <input type="checkbox" class="task-list-item-checkbox source-status-checkbox"
 *                  data-task="x">
 *
 *   and the plugin's own scoped CSS forces:
 *
 *       .task-status-marker .task-list-item { display: contents !important }
 *       .task-status-marker .source-status-checkbox { appearance: none !important }
 *
 *   Three independent failures resulted:
 *
 *     1. NO `.contains-task-list` ANCESTOR  → every ::before/::after rule
 *        failed to match. No box, no tick was ever drawn.
 *     2. `.task-list-item` IS A <span> WITH `display: contents` → it
 *        generates no box, so even a matching absolutely-positioned
 *        pseudo-element would have had no containing block.
 *     3. THE PLUGIN STRIPS `appearance` AND PAINTS NOTHING ITSELF — it
 *        explicitly delegates rendering to the theme. Obsidianite had
 *        exactly ONE `input[type=` rule in 1,481 lines, and that rule only
 *        set `opacity: 0`. Nothing was left to draw the control.
 *
 *   Inside card bodies (where MarkdownRenderer DOES emit a real list) the
 *   outcome was worse: the plugin's `padding-left: 0 !important` removed the
 *   gutter, `.task { overflow: hidden }` clipped the substitute at left:-25px,
 *   and Obsidianite's `opacity: 0` still won on the nested subtask inputs.
 *   Doubly invisible.
 *
 * ── HOW PRIME AVOIDS THE STRUCTURAL ASSUMPTION ──────────────────────────
 *
 *   RULE 2 (docs/13 §2): a component's rendering must depend only on the
 *   element that semantically IS that component — never on an ancestor.
 *
 *   Therefore: THE CHECKBOX IS THE INPUT.
 *
 *     · `appearance: none` on the input itself
 *     · the box     = the input's own border + background
 *     · the marker  = the input's own ::after at inset: 0
 *     · no ancestor selector participates in painting
 *     · `opacity` is never used to hide anything
 *
 *   Consequences:
 *     · no `.contains-task-list` needed          → failure 1 impossible
 *     · no parent box needed                     → failure 2 impossible
 *     · the theme accepts the plugin's delegation → failure 3 resolved
 *     · nothing is positioned outside the input  → clipping impossible
 *     · no gutter is reserved                    → padding overrides harmless
 *
 *   This is a THEME COMPONENT, not a plugin patch. It works in any DOM that
 *   contains an <input type="checkbox">, which is the only thing it
 *   semantically requires. Task List Kanban needs no special treatment for
 *   correctness — see src/compat/95 for the two purely cosmetic sizing rules.
 *
 * Full analysis: docs/04-bug-01-task-list-kanban.md
 * ──────────────────────────────────────────────────────────────────────── */

/* ══ CORE · the checkbox is the input ═══════════════════════════════════ */

input[type='checkbox'] {
	appearance: none;
	-webkit-appearance: none;

	position: relative;
	flex-shrink: 0;
	box-sizing: border-box;
	display: inline-block;
	vertical-align: middle;

	width: var(--prime-checkbox-size);
	height: var(--prime-checkbox-size);
	margin: 0 var(--prime-checkbox-gap) 0 0;
	padding: 0;

	background-color: var(--prime-checkbox-bg);
	border: var(--prime-checkbox-border-width) solid var(--prime-checkbox-border-color);
	border-radius: var(--prime-checkbox-shape-radius);

	cursor: var(--prime-cursor);

	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard),
		border-color var(--prime-motion-fast) var(--prime-ease-standard),
		box-shadow var(--prime-motion-superfast) var(--prime-ease-standard);
}

input[type='checkbox']:hover {
	border-color: var(--prime-checkbox-border-hover);
	box-shadow: var(--prime-checkbox-shadow-hover);
}

input[type='checkbox']:focus-visible {
	outline: 2px solid var(--prime-border-focus);
	outline-offset: 2px;
}

/* ── The marker ───────────────────────────────────────────────────────────
 * Drawn on the INPUT'S OWN pseudo-element, at inset:0 of the input. It can
 * never be clipped by an ancestor's overflow and never depends on a parent's
 * box, because it is inside the box it decorates. */

input[type='checkbox']::after {
	content: '';
	position: absolute;
	inset: 0;

	background-color: var(--prime-checkbox-marker-color);

	-webkit-mask-image: var(--prime-checkbox-icon-check);
	mask-image: var(--prime-checkbox-icon-check);
	-webkit-mask-position: center;
	mask-position: center;
	-webkit-mask-repeat: no-repeat;
	mask-repeat: no-repeat;
	-webkit-mask-size: var(--prime-checkbox-marker-size);
	mask-size: var(--prime-checkbox-marker-size);

	/* Obsidianite's "bounce" feel, reimplemented as a single overshoot
	 * transform instead of a border-width keyframe. Same perceived motion,
	 * compositor-only, no layout cost, and user-tunable. */
	transform: scale(0.4);
	opacity: 0;
	transition: transform var(--prime-motion-fast) var(--prime-ease-overshoot),
		opacity var(--prime-motion-superfast) linear;
}

/* ── Checked ──────────────────────────────────────────────────────────── */

input[type='checkbox']:checked {
	background-color: var(--prime-checkbox-checked-bg);
	border-color: var(--prime-checkbox-checked-border);
}

input[type='checkbox']:checked::after {
	transform: scale(1);
	opacity: 1;
}

body.prime-anim-no-checkbox input[type='checkbox']::after {
	transition: none;
}

/* ── Indeterminate ────────────────────────────────────────────────────── */

input[type='checkbox']:indeterminate {
	background-color: var(--prime-checkbox-checked-bg);
	border-color: var(--prime-checkbox-checked-border);
}

input[type='checkbox']:indeterminate::after {
	-webkit-mask-image: var(--prime-checkbox-icon-dash);
	mask-image: var(--prime-checkbox-icon-dash);
	transform: scale(1);
	opacity: 1;
}

/* ══ TASK STATES · data-task ════════════════════════════════════════════
 *
 * Three selector shapes are required to cover every DOM Obsidian and its
 * plugins produce. All three are ancestor-agnostic in the sense that matters:
 * none of them requires a specific ancestor in order to PAINT — the li[]
 * forms only narrow which input is matched.
 *
 *   input[data-task="X"]          Task List Kanban (sets data-task on the
 *                                 input itself — main.js:15423)
 *   li[data-task="X"] > input     Obsidian tight lists (both modes)
 *   li[data-task="X"] > p > input Obsidian loose lists (Reading Mode)
 *
 * Obsidianite supported NO custom states at all. This is new capability.
 * ─────────────────────────────────────────────────────────────────────── */

/* ── [/] In progress ──────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='/'],
li[data-task='/'] > input[type='checkbox']:checked,
li[data-task='/'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-progress-color);
	border-color: var(--prime-task-progress-color);
}

input[type='checkbox']:checked[data-task='/']::after,
li[data-task='/'] > input[type='checkbox']:checked::after,
li[data-task='/'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-dash);
	mask-image: var(--prime-checkbox-icon-dash);
}

/* ── [-] Cancelled ────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='-'],
li[data-task='-'] > input[type='checkbox']:checked,
li[data-task='-'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-cancelled-color);
	border-color: var(--prime-task-cancelled-color);
}

input[type='checkbox']:checked[data-task='-']::after,
li[data-task='-'] > input[type='checkbox']:checked::after,
li[data-task='-'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-cross);
	mask-image: var(--prime-checkbox-icon-cross);
}

/* ── [>] Forwarded ────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='>'],
li[data-task='>'] > input[type='checkbox']:checked,
li[data-task='>'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-forwarded-color);
	border-color: var(--prime-task-forwarded-color);
}

input[type='checkbox']:checked[data-task='>']::after,
li[data-task='>'] > input[type='checkbox']:checked::after,
li[data-task='>'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-forward);
	mask-image: var(--prime-checkbox-icon-forward);
}

/* ── [<] Scheduled ────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='<'],
li[data-task='<'] > input[type='checkbox']:checked,
li[data-task='<'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-forwarded-color);
	border-color: var(--prime-task-forwarded-color);
}

input[type='checkbox']:checked[data-task='<']::after,
li[data-task='<'] > input[type='checkbox']:checked::after,
li[data-task='<'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-back);
	mask-image: var(--prime-checkbox-icon-back);
}

/* ── [?] Question ─────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='?'],
li[data-task='?'] > input[type='checkbox']:checked,
li[data-task='?'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-question-color);
	border-color: var(--prime-task-question-color);
}

input[type='checkbox']:checked[data-task='?']::after,
li[data-task='?'] > input[type='checkbox']:checked::after,
li[data-task='?'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-question);
	mask-image: var(--prime-checkbox-icon-question);
}

/* ── [!] Important ────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='!'],
li[data-task='!'] > input[type='checkbox']:checked,
li[data-task='!'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-important-color);
	border-color: var(--prime-task-important-color);
}

input[type='checkbox']:checked[data-task='!']::after,
li[data-task='!'] > input[type='checkbox']:checked::after,
li[data-task='!'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-bang);
	mask-image: var(--prime-checkbox-icon-bang);
}

/* ── [*] Star ─────────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='*'],
li[data-task='*'] > input[type='checkbox']:checked,
li[data-task='*'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-star-color);
	border-color: var(--prime-task-star-color);
}

input[type='checkbox']:checked[data-task='*']::after,
li[data-task='*'] > input[type='checkbox']:checked::after,
li[data-task='*'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-star);
	mask-image: var(--prime-checkbox-icon-star);
}

/* ── ["] Quote ────────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='"'],
li[data-task='"'] > input[type='checkbox']:checked,
li[data-task='"'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-quote-color);
	border-color: var(--prime-task-quote-color);
}

input[type='checkbox']:checked[data-task='"']::after,
li[data-task='"'] > input[type='checkbox']:checked::after,
li[data-task='"'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-quote);
	mask-image: var(--prime-checkbox-icon-quote);
}

/* ── [i] Info ─────────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='i'],
li[data-task='i'] > input[type='checkbox']:checked,
li[data-task='i'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-info-color);
	border-color: var(--prime-task-info-color);
}

input[type='checkbox']:checked[data-task='i']::after,
li[data-task='i'] > input[type='checkbox']:checked::after,
li[data-task='i'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-info);
	mask-image: var(--prime-checkbox-icon-info);
}

/* ── [b] Bookmark ─────────────────────────────────────────────────────── */
input[type='checkbox']:checked[data-task='b'],
li[data-task='b'] > input[type='checkbox']:checked,
li[data-task='b'] > p > input[type='checkbox']:checked {
	background-color: var(--prime-task-bookmark-color);
	border-color: var(--prime-task-bookmark-color);
}

input[type='checkbox']:checked[data-task='b']::after,
li[data-task='b'] > input[type='checkbox']:checked::after,
li[data-task='b'] > p > input[type='checkbox']:checked::after {
	-webkit-mask-image: var(--prime-checkbox-icon-bookmark);
	mask-image: var(--prime-checkbox-icon-bookmark);
}

/* ══ TASK LINE TEXT ═════════════════════════════════════════════════════ */

.markdown-rendered li.task-list-item.is-checked,
.markdown-source-view.mod-cm6 .HyperMD-task-line[data-task='x'],
.markdown-source-view.mod-cm6 .HyperMD-task-line[data-task='X'] {
	color: var(--prime-task-done-color);
	text-decoration: var(--prime-task-done-decoration);
	text-decoration-color: color-mix(
		in srgb,
		var(--prime-task-done-color) 60%,
		transparent
	);
	opacity: var(--prime-task-done-opacity);
}

/* A completed parent must not strike through its incomplete children */
.markdown-rendered li.task-list-item.is-checked ul > li:not(.is-checked),
.markdown-rendered li.task-list-item.is-checked ol > li:not(.is-checked) {
	color: var(--prime-text-normal);
	text-decoration: none;
	opacity: 1;
}

/* Cancelled tasks read as struck-through regardless of checked state */
.markdown-rendered li.task-list-item[data-task='-'],
.markdown-source-view.mod-cm6 .HyperMD-task-line[data-task='-'] {
	color: var(--prime-task-cancelled-color);
	text-decoration: line-through;
}

body.prime-no-task-strike .markdown-rendered li.task-list-item.is-checked,
body.prime-no-task-strike .markdown-source-view.mod-cm6 .HyperMD-task-line[data-task='x'] {
	text-decoration: none;
}

/* ══ LAYOUT ═════════════════════════════════════════════════════════════
 * Minimal, because the input now occupies its own inline box in normal flow.
 * Compare with Obsidianite, which needed a 30px gutter, a -3em text-indent
 * and a -80px collapse-indicator offset to support its parent-painted box. */

.markdown-rendered li.task-list-item {
	list-style: none;
}

.markdown-rendered ul.contains-task-list {
	padding-inline-start: 1.6em;
}

.markdown-rendered .task-list-item-checkbox {
	margin-inline-end: var(--prime-checkbox-gap);
}

/* Live Preview vertical alignment */
.markdown-source-view.mod-cm6 .task-list-item-checkbox {
	position: relative;
	top: var(--prime-checkbox-top);
}

.markdown-source-view.mod-cm6 .task-list-label {
	padding-top: 0;
}

/* ── COMPONENT · TABLES ────────────────────────────────────────────────────
 * NEW IN PRIME. Obsidianite had no table styling (defect F-17).
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered table {
	border-collapse: separate;
	border-spacing: 0;
	width: 100%;
	margin-block: 1em;
	border: var(--prime-table-border-width) solid var(--prime-table-border-color);
	border-radius: var(--prime-table-radius);
	overflow: hidden;
}

.markdown-rendered th,
.markdown-rendered td {
	padding: var(--prime-table-cell-padding);
	border-bottom: var(--prime-table-border-width) solid var(--prime-table-border-color);
	border-right: var(--prime-table-border-width) solid var(--prime-table-border-color);
}

.markdown-rendered th:last-child,
.markdown-rendered td:last-child {
	border-right: none;
}

.markdown-rendered tbody tr:last-child td {
	border-bottom: none;
}

/* ── Header ───────────────────────────────────────────────────────────── */

.markdown-rendered thead th {
	background-color: var(--prime-table-header-bg);
	color: var(--prime-table-header-color);
	font-weight: var(--prime-table-header-weight);
	text-transform: var(--prime-table-header-transform);
	letter-spacing: 0.01em;
	border-bottom: var(--prime-border-width-thick) solid var(--prime-table-border-color);
}

/* ── Rows ─────────────────────────────────────────────────────────────── */

.markdown-rendered tbody tr {
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered tbody tr:hover {
	background-color: var(--prime-table-row-hover-bg);
}

/* Striping is opt-in via the Striped variant, which raises the opacity */
.markdown-rendered tbody tr:nth-child(even) {
	background-color: color-mix(
		in srgb,
		var(--prime-table-stripe-bg) var(--prime-table-stripe-opacity),
		transparent
	);
}

/* ── Live Preview tables ──────────────────────────────────────────────── */

.markdown-source-view.mod-cm6 .cm-table-widget table {
	border-color: var(--prime-table-border-color);
}

.markdown-source-view.mod-cm6 .table-cell-wrapper {
	color: var(--prime-text-normal);
}

/* ── Table controls ───────────────────────────────────────────────────── */

.markdown-source-view.mod-cm6 .table-col-btn,
.markdown-source-view.mod-cm6 .table-row-btn {
	background-color: var(--prime-bg-secondary);
	color: var(--prime-text-muted);
	border-radius: var(--prime-radius-xs);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-source-view.mod-cm6 .table-col-btn:hover,
.markdown-source-view.mod-cm6 .table-row-btn:hover {
	background-color: var(--prime-surface-active);
	color: var(--prime-accent);
}

/* ── COMPONENT · TAGS ──────────────────────────────────────────────────────
 *
 * Obsidianite's small italic tag pill is retained (keeper K-7).
 *
 * DROPPED: Obsidianite hard-coded nine specific tag names with bespoke
 * colours (#todo, #working-draft, #notes, #knowledge, #writing, #ideas plus
 * Simplified Chinese aliases 待完成 / 笔记 / 知识 / 文章 / 想法). Those were
 * personal to the original author and unusable to anyone else.
 *
 * Prime replaces them with six USER-DEFINABLE colour slots, driven entirely
 * by Style Settings — the user supplies both the tag name and the colour.
 * See src/01-settings.css section 13.1.
 *
 * FIX: Obsidianite needed `background-color: … !important` on :hover purely
 * to defeat Obsidian's own hover rule. Prime achieves the same with correct
 * specificity and no !important.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered a.tag,
.cm-s-obsidian .cm-hashtag {
	color: var(--prime-tag-color);
	background-color: var(--prime-tag-bg);
	border: var(--prime-tag-border-width) solid var(--prime-tag-border-color);
	border-radius: var(--prime-tag-radius);
	padding: var(--prime-tag-padding-y) var(--prime-tag-padding-x);
	font-family: var(--prime-font-text);
	font-size: var(--prime-tag-size);
	font-weight: var(--prime-tag-weight);
	font-style: var(--prime-tag-style);
	text-decoration: var(--prime-tag-decoration);
	white-space: nowrap;
	line-height: 1.4;
	transition: color var(--prime-motion-fast) var(--prime-ease-standard),
		background-color var(--prime-motion-fast) var(--prime-ease-standard),
		border-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered a.tag:hover,
.cm-s-obsidian .cm-hashtag:hover {
	color: var(--prime-tag-hover-color);
	background-color: var(--prime-tag-hover-bg);
	border-color: var(--prime-border-hover);
	text-decoration: none;
}

/* ── Live Preview hashtag segments ────────────────────────────────────────
 * CM6 splits a tag into .cm-hashtag-begin (the #) and .cm-hashtag-end (the
 * name). Rounding must be applied to the outer edges only, or each segment
 * gets its own pill. */

.cm-s-obsidian .cm-hashtag-begin {
	border-top-right-radius: 0;
	border-bottom-right-radius: 0;
	padding-inline-end: 0;
	color: var(--prime-text-faint);
}

.cm-s-obsidian .cm-hashtag-end {
	border-top-left-radius: 0;
	border-bottom-left-radius: 0;
	padding-inline-start: 0;
}

/* ── Tags in headings inherit the heading scale ───────────────────────── */

.markdown-rendered :is(h1, h2, h3, h4, h5, h6) a.tag {
	font-size: inherit;
	vertical-align: baseline;
}

/* ── User-definable colour slots ──────────────────────────────────────────
 * Each slot pairs a tag name (variable-text) with a colour
 * (variable-themed-color). The attribute selector is generated from the
 * user's chosen name via the --prime-tag-N-name token, which Style Settings
 * writes. Slots are inert until configured. */

.markdown-rendered a.tag[href*='#'][data-prime-slot],
.cm-s-obsidian .cm-hashtag[data-prime-slot] {
	color: var(--prime-tag-slot-color, var(--prime-tag-color));
	background-color: var(--prime-tag-slot-bg, var(--prime-tag-bg));
}

/* ── COMPONENT · EMBEDS & TRANSCLUSIONS ────────────────────────────────────
 * NEW IN PRIME. Obsidianite had no embed styling (defect F-17).
 *
 * Note that embed CONTENT is styled automatically, because every Prime
 * component targets `.markdown-rendered` rather than `.markdown-preview-view`
 * (see src/editor/42). This file styles the embed CONTAINER only.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered .markdown-embed,
.markdown-rendered .file-embed {
	background-color: var(--prime-embed-bg);
	border: var(--prime-embed-border-width) solid var(--prime-embed-border-color);
	border-left-width: var(--prime-quote-border-width);
	border-left-color: var(--prime-accent-muted);
	border-radius: var(--prime-embed-radius);
	padding: var(--prime-embed-padding);
	margin-block: 0.8em;
	transition: border-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered .markdown-embed:hover {
	border-color: var(--prime-border-hover);
	border-left-color: var(--prime-accent);
}

.markdown-rendered .markdown-embed-title,
.markdown-rendered .embed-title {
	color: var(--prime-embed-title-color);
	font-size: var(--prime-embed-title-size);
	font-weight: var(--prime-embed-title-weight);
	line-height: 1.5;
	padding-bottom: var(--prime-space-1);
	border-bottom: var(--prime-border-width) solid var(--prime-border);
	margin-bottom: var(--prime-space-2);
	text-align: left;
}

.markdown-rendered .markdown-embed-title:empty,
.markdown-rendered .embed-title:empty {
	display: none;
}

.markdown-rendered .markdown-embed-link,
.markdown-rendered .file-embed-link {
	color: var(--prime-text-faint);
	opacity: 0;
	transition: opacity var(--prime-motion-fast) var(--prime-ease-standard),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

.markdown-rendered .markdown-embed:hover .markdown-embed-link,
.markdown-rendered .file-embed:hover .file-embed-link {
	opacity: 1;
}

.markdown-rendered .markdown-embed-link:hover {
	color: var(--prime-accent);
}

/* Embedded content should not re-apply the outer note's top margin */
.markdown-rendered .markdown-embed-content > .markdown-preview-view,
.markdown-rendered .markdown-embed-content .markdown-rendered > *:first-child {
	margin-block-start: 0;
	padding: 0;
}

/* ── Unresolved / broken embeds ───────────────────────────────────────── */

.markdown-rendered .markdown-embed.is-loaded:empty::after,
.markdown-rendered .file-embed.mod-empty {
	color: var(--prime-text-faint);
	font-style: italic;
}

/* ── Live Preview inline embeds ───────────────────────────────────────── */

.markdown-source-view.mod-cm6 .internal-embed {
	border-radius: var(--prime-embed-radius);
}

/* ── Canvas cards ─────────────────────────────────────────────────────── */

.canvas-node-content {
	border-radius: var(--prime-radius-m);
}

.canvas-node-container {
	border-radius: var(--prime-radius-m);
	border-color: var(--prime-border);
}

.canvas-node.is-selected .canvas-node-container {
	border-color: var(--prime-accent);
}

/* ── COMPONENT · PROPERTIES / FRONTMATTER ──────────────────────────────────
 * NEW IN PRIME. Obsidianite had no properties styling (defect F-17).
 * ──────────────────────────────────────────────────────────────────────── */

.metadata-container {
	background-color: var(--prime-props-bg);
	border: var(--prime-border-width) solid var(--prime-border);
	border-radius: var(--prime-props-radius);
	padding: var(--prime-space-2) var(--prime-space-3);
	margin-block-end: var(--prime-space-4);
	font-size: var(--prime-props-size);
}

.metadata-properties-heading {
	color: var(--prime-text-muted);
	font-weight: var(--prime-props-key-weight);
}

.metadata-property {
	border-radius: var(--prime-radius-xs);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.metadata-property:hover {
	background-color: var(--prime-surface-hover);
}

.metadata-property-key,
.metadata-property-key-input {
	color: var(--prime-props-key-color);
	font-weight: var(--prime-props-key-weight);
}

.metadata-property-value,
.metadata-property-value .metadata-input-longtext {
	color: var(--prime-props-value-color);
}

.metadata-property-icon {
	color: var(--prime-text-faint);
}

.metadata-property:hover .metadata-property-icon {
	color: var(--prime-accent);
}

/* Multi-value pills (tags, lists) */
.metadata-property .multi-select-pill {
	background-color: var(--prime-tag-bg);
	color: var(--prime-tag-color);
	border: var(--prime-border-width) solid var(--prime-tag-border-color);
	border-radius: var(--prime-tag-radius);
	transition: background-color var(--prime-motion-fast) var(--prime-ease-standard);
}

.metadata-property .multi-select-pill:hover {
	background-color: var(--prime-tag-hover-bg);
}

.metadata-add-button {
	color: var(--prime-text-faint);
	transition: color var(--prime-motion-fast) var(--prime-ease-standard);
}

.metadata-add-button:hover {
	color: var(--prime-accent);
}

/* Checkbox properties reuse the core checkbox component automatically —
 * another consequence of styling the input rather than a parent. */

/* ── Raw YAML frontmatter (source mode) ───────────────────────────────── */

.markdown-source-view.mod-cm6 .cm-line.HyperMD-frontmatter {
	background-color: var(--prime-bg-secondary);
	color: var(--prime-text-muted);
	font-family: var(--prime-font-monospace);
	font-size: 0.88em;
}

.markdown-source-view.mod-cm6 .cm-hmd-frontmatter {
	color: var(--prime-text-muted);
}

.markdown-source-view.mod-cm6 .HyperMD-frontmatter-start,
.markdown-source-view.mod-cm6 .HyperMD-frontmatter-end {
	color: var(--prime-text-faint);
	border-color: var(--prime-border);
}

/* ── COMPONENT · MISCELLANEOUS ─────────────────────────────────────────── */

/* ── Mermaid ──────────────────────────────────────────────────────────── */

.markdown-rendered .mermaid {
	background-color: transparent;
}

.markdown-rendered .mermaid .node rect,
.markdown-rendered .mermaid .node circle,
.markdown-rendered .mermaid .node polygon {
	fill: var(--prime-bg-secondary);
	stroke: var(--prime-accent);
}

.markdown-rendered .mermaid .edgePath .path {
	stroke: var(--prime-text-muted);
}

/* ── Graph view ───────────────────────────────────────────────────────── */

.graph-view.color-fill {
	color: var(--prime-text-muted);
}

.graph-view.color-fill-focused {
	color: var(--prime-accent);
}

.graph-view.color-line {
	color: var(--prime-border-strong);
}

.graph-view.color-text {
	color: var(--prime-text-normal);
}

.graph-view.color-circle {
	color: var(--prime-accent);
}

/* ── Task / progress bars (generic) ───────────────────────────────────── */

progress {
	accent-color: var(--prime-accent);
}

/* ── Print ────────────────────────────────────────────────────────────── */

@media print {
	.markdown-rendered {
		color: #000;
		background: #fff;
	}

	/* Gradient-clipped text does not print. Force solid. */
	.markdown-rendered strong,
	.markdown-rendered :is(h1, h2, h3, h4, h5, h6) {
		background-image: none;
		-webkit-text-fill-color: initial;
		color: #000;
	}
}

/* ── Forced colours / Windows High Contrast ───────────────────────────────
 * a11y: gradient-clipped text is invisible in forced-colors mode because the
 * background is discarded while the transparent fill is retained. Neither
 * source theme handled this. */

@media (forced-colors: active) {
	.markdown-rendered strong,
	.cm-s-obsidian .cm-strong,
	.markdown-rendered :is(h1, h2, h3, h4, h5, h6) {
		background-image: none;
		-webkit-text-fill-color: initial;
		forced-color-adjust: auto;
	}

	input[type='checkbox'] {
		forced-color-adjust: auto;
		appearance: auto;
		-webkit-appearance: auto;
	}
}

/* ── VARIANTS · DIVIDERS ───────────────────────────────────────────────────
 *
 * VARIANT CONTRACT (docs/08 §2):
 *   A variant may ONLY reassign component tokens or toggle a decorative
 *   pseudo-element's display. It must never redefine layout the base file
 *   owns, and must never hard-code a value the user might customise.
 *
 * Exactly one variant class is always present on <body>, guaranteed by
 * allowEmpty:false + a declared default in the class-select.
 * ──────────────────────────────────────────────────────────────────────── */

/* ── Standard · a clean solid rule ────────────────────────────────────── */

body.prime-divider-standard {
	--prime-divider-thickness: 1px;
	--prime-divider-image: none;
	--prime-divider-glyph-display: none;
	--prime-divider-opacity: 1;
	--prime-divider-color: var(--prime-border-strong);
}

/* ── Minimal · barely-there, tight spacing ────────────────────────────── */

body.prime-divider-minimal {
	--prime-divider-thickness: 1px;
	--prime-divider-image: none;
	--prime-divider-glyph-display: none;
	--prime-divider-margin: 1.6em;
	--prime-divider-opacity: 0.45;
	--prime-divider-color: var(--prime-border-strong);
}

/* ── Gradient · Obsidianite's fading rule, no glyph ───────────────────── */

body.prime-divider-gradient {
	--prime-divider-image: linear-gradient(
		90deg,
		transparent,
		var(--prime-divider-grad-1),
		var(--prime-divider-grad-2),
		transparent
	);
	--prime-divider-glyph-display: none;
}

/* ── Decorative · the full Obsidianite treatment (default) ────────────────
 * Gradient rule + the rotated § glyph punching through it. This is the
 * stock Obsidianite look and Prime's default. */

body.prime-divider-decorative {
	--prime-divider-image: linear-gradient(
		90deg,
		transparent,
		var(--prime-divider-grad-1),
		var(--prime-divider-grad-2),
		transparent
	);
	--prime-divider-glyph-display: inline-block;
}

/* ── Animated · Decorative plus a hover response ──────────────────────────
 * Deliberately hover-triggered rather than an infinite keyframe: an
 * always-running animation on every divider in a long note is exactly the
 * idle cost the performance rules forbid (docs/09 §B4). */

body.prime-divider-animated {
	--prime-divider-image: linear-gradient(
		90deg,
		transparent,
		var(--prime-divider-grad-1),
		var(--prime-divider-grad-2),
		transparent
	);
	--prime-divider-glyph-display: inline-block;
}

body.prime-divider-animated:not(.prime-animations-off) .markdown-rendered hr:hover::after {
	transform: translate(-50%, -50%) rotate(calc(var(--prime-divider-glyph-rotate) + 180deg))
		scale(1.15);
	color: var(--prime-accent);
}

/* ── VARIANTS · HEADINGS ───────────────────────────────────────────────────
 * Same contract as dividers: reassign tokens only.
 * ──────────────────────────────────────────────────────────────────────── */

/* ── Obsidianite (default) ────────────────────────────────────────────────
 * H1 is accent-coloured with no rule; H2-H6 carry the magenta underline
 * fading to transparent. This is the stock Obsidianite signature.
 *
 * Note the gradient terminates in `transparent`, not a hard-coded #100e17
 * as Obsidianite did — so it survives the user changing the background. */

body.prime-heading-obsidianite {
	--prime-h-underline-display: block;
	--prime-h-underline-image: linear-gradient(
		to right,
		var(--prime-h-underline-color),
		transparent 55%
	);
	--prime-h-bar-display: none;
}

/* ── Minimal · size and weight only ───────────────────────────────────── */

body.prime-heading-minimal {
	--prime-h-underline-display: none;
	--prime-h-bar-display: none;
	--prime-h-margin-top: 1.5em;
	--prime-h-margin-bottom: 0.5em;
}

/* ── Gradient · gradient-clipped heading text ─────────────────────────────
 * Gated behind the gradient master switch. Falls back to the solid
 * per-level colour when gradients are off, because that colour is always
 * declared in the base file. */

body.prime-heading-gradient {
	--prime-h-underline-display: none;
	--prime-h-bar-display: none;
}

body.prime-heading-gradient.prime-gradients-on .markdown-rendered :is(h1, h2, h3) {
	background-image: var(--prime-h-gradient);
	-webkit-background-clip: text;
	background-clip: text;
	-webkit-text-fill-color: transparent;
	width: fit-content;
}

/* a11y + Bug #2 defence: nested inline elements must not inherit the
 * transparent fill. Same reset pattern as 53-emphasis.css. */
body.prime-heading-gradient
	.markdown-rendered
	:is(h1, h2, h3)
	:is(code, kbd, mark, a, .tag, .math) {
	-webkit-text-fill-color: initial;
	background-image: none;
	-webkit-background-clip: initial;
	background-clip: initial;
}

/* ── Bordered · uniform full-width rule, documentation style ──────────── */

body.prime-heading-bordered {
	--prime-h-underline-display: block;
	--prime-h-underline-image: linear-gradient(
		to right,
		var(--prime-h-underline-color),
		var(--prime-h-underline-color)
	);
	--prime-h-bar-display: none;
	--prime-h-underline-width: 1px;
}

/* ── Accent Bar · a short vertical bar to the left ────────────────────── */

body.prime-heading-accentbar {
	--prime-h-underline-display: none;
	--prime-h-bar-display: block;
	--prime-h-bar-width: 3px;
}

/* ── VARIANTS · SCAFFOLD ───────────────────────────────────────────────────
 *
 * Per brief §8 and §20, only dividers and headings ship a full variant set
 * in v1. The components below get their class-select, their default option,
 * and their variant block established NOW so that:
 *
 *   1. The Style Settings key and its default are locked in from v1.0. A
 *      later addition can never invalidate an existing user's saved config
 *      (risk R-12 — Style Settings discards orphaned keys silently).
 *   2. The base/variant separation is already correct, so adding option two
 *      is the five-step recipe in docs/08 §6 with no core-file edits.
 *
 * Each block below is a real, functioning default — not a placeholder.
 * ──────────────────────────────────────────────────────────────────────── */

/* ── Callouts ─────────────────────────────────────────────────────────── */

body.prime-callout-standard {
	--prime-callout-bg-opacity: 8%;
	--prime-callout-title-bg-opacity: 14%;
	--prime-callout-accent-width: 3px;
	--prime-callout-icon-display: flex;
}

/* ── Code blocks ──────────────────────────────────────────────────────── */

body.prime-codeblock-standard {
	--prime-code-border-width: 1px;
	--prime-code-radius: var(--prime-radius-m);
}

/* ── Checkboxes ───────────────────────────────────────────────────────── */

body.prime-checkbox-rounded {
	--prime-checkbox-shape-radius: var(--prime-radius-xs);
}

/* ── Tags ─────────────────────────────────────────────────────────────── */

body.prime-tag-pill {
	--prime-tag-radius: var(--prime-radius-pill);
	--prime-tag-border-width: 1px;
	--prime-tag-decoration: none;
}

/* ── Links ────────────────────────────────────────────────────────────── */

body.prime-link-sweep {
	--prime-link-sweep-rest: 5px;
	--prime-link-sweep-hover: 60px;
	--prime-link-decoration: none;
}

/* ── Tables ───────────────────────────────────────────────────────────── */

body.prime-table-standard {
	--prime-table-stripe-opacity: 0%;
	--prime-table-border-width: 1px;
}

/* ── Blockquotes ──────────────────────────────────────────────────────── */

body.prime-blockquote-obsidianite {
	--prime-quote-bar-display: block;
	--prime-quote-glyph-display: none;
}

/* ── Status bar ───────────────────────────────────────────────────────── */

body.prime-statusbar-floating {
	--prime-statusbar-opacity: 0.45;
}

body.prime-statusbar-docked {
	--prime-statusbar-opacity: 1;
}

/* ── SYSTEM · GRADIENTS ────────────────────────────────────────────────────
 *
 * Global gradient system (brief §9).
 *
 * THREE-LEVEL CASCADE, resolved entirely by CSS variable fallback chaining —
 * no branching, no duplicated rules:
 *
 *   Level 1  --prime-grad-1/-2/-angle          global      (tokens/14)
 *   Level 2  --prime-<c>-grad-1/-2/-angle      component   (tokens/14,
 *                                              each defaulting to Level 1)
 *   Level 3  --prime-<c>-gradient              resolved    (here)
 *
 * A user who sets only the global colours gets consistent gradients
 * everywhere. A user who sets a component's colours overrides just that
 * component while the rest continue to track the global.
 *
 * THIS FILE LOADS AFTER ALL COMPONENTS, so the master off-switch can
 * neutralise them without specificity tricks (rule VR-2).
 * ──────────────────────────────────────────────────────────────────────── */

/* ── Level 3 · resolved gradients ─────────────────────────────────────── */

body {
	--prime-h-gradient: linear-gradient(
		var(--prime-h-grad-angle),
		var(--prime-h-grad-1),
		var(--prime-h-grad-2)
	);

	--prime-bold-gradient: linear-gradient(
		var(--prime-bold-grad-angle),
		var(--prime-bold-grad-1),
		var(--prime-bold-grad-2)
	);

	--prime-divider-gradient: linear-gradient(
		90deg,
		transparent,
		var(--prime-divider-grad-1),
		var(--prime-divider-grad-2),
		transparent
	);

	--prime-link-gradient: linear-gradient(
		90deg,
		var(--prime-link-grad-1),
		var(--prime-link-grad-2)
	);
}

/* ══ MASTER OFF-SWITCH ══════════════════════════════════════════════════
 *
 * When gradients are disabled, every component falls back to the solid
 * colour it ALREADY declares unconditionally in its own file. Nothing needs
 * recomputing and nothing can end up invisible.
 *
 * This is also LAYER 4 of the Bug #2 fix: with gradients off,
 * -webkit-text-fill-color: transparent is never set anywhere in the theme,
 * so the inheritance failure is structurally impossible. It is the
 * guaranteed user escape hatch.
 */

body.prime-gradients-off {
	--prime-h-gradient: none;
	--prime-bold-gradient: none;
	--prime-link-gradient: none;
}

body.prime-gradients-off :is(strong, .cm-strong),
body.prime-gradients-off .markdown-rendered :is(h1, h2, h3, h4, h5, h6) {
	background-image: none;
	-webkit-background-clip: initial;
	background-clip: initial;
	-webkit-text-fill-color: initial;
}

/* Explicit solid restatements, so the fallback is unambiguous. */
body.prime-gradients-off :is(.markdown-rendered strong, .cm-s-obsidian .cm-strong) {
	color: var(--prime-bold-color);
}

body.prime-gradients-off .markdown-rendered h1 { color: var(--prime-h1-color); }
body.prime-gradients-off .markdown-rendered h2 { color: var(--prime-h2-color); }
body.prime-gradients-off .markdown-rendered h3 { color: var(--prime-h3-color); }
body.prime-gradients-off .markdown-rendered h4 { color: var(--prime-h4-color); }
body.prime-gradients-off .markdown-rendered h5 { color: var(--prime-h5-color); }
body.prime-gradients-off .markdown-rendered h6 { color: var(--prime-h6-color); }

/* Dividers keep a solid rule rather than losing their line entirely. */
body.prime-gradients-off {
	--prime-divider-gradient: none;
}

body.prime-gradients-off.prime-divider-gradient,
body.prime-gradients-off.prime-divider-decorative,
body.prime-gradients-off.prime-divider-animated {
	--prime-divider-image: none;
}

/* Blockquote decorative bars become solid rather than gradient. */
body.prime-gradients-off .markdown-rendered blockquote:not(.callout)::before,
body.prime-gradients-off .markdown-rendered blockquote:not(.callout)::after {
	background-image: none;
	background-color: var(--prime-quote-border-color);
	opacity: 0.5;
}

/* ── SYSTEM · MOTION ───────────────────────────────────────────────────────
 *
 * CLEAN-ROOM NOTE (decision G-1)
 *
 * Primary was studied as a quality benchmark, not a source. The lessons
 * taken are architectural, not textual:
 *
 *   - motion quality comes from CONSISTENT SHORT TRANSITIONS on interactive
 *     states, not from elaborate choreography (Primary: 53 transitions,
 *     3 keyframes — a ratio worth matching)
 *   - a NAMED duration + easing scale keeps a large theme coherent
 *   - an OVERSHOOT stop makes an entry animation feel physical
 *
 * Everything below — the token names, the durations, the bezier values, the
 * keyframe stops — was authored independently for Prime. No Primary code is
 * present. Two things Primary does were deliberately NOT reproduced:
 *
 *   1. Its margin-animating popup keyframe. Animating `margin-top` triggers
 *      layout on every frame; Prime uses `transform` (PR-3).
 *   2. Its malformed `transition: border, box-shadow, transform <timing>`
 *      lists, where only the last segment receives the timing function.
 *      Every Prime transition is an explicit property/duration/easing triplet.
 *
 * Prime also ADDS what Primary lacks entirely: prefers-reduced-motion support.
 * ──────────────────────────────────────────────────────────────────────── */

/* ── Keyframes · compositor-only properties ───────────────────────────── */

@keyframes prime-enter-up {
	from {
		opacity: 0;
		transform: translate3d(0, 7px, 0) scale(0.985);
	}
	to {
		opacity: 1;
		transform: translate3d(0, 0, 0) scale(1);
	}
}

@keyframes prime-enter-down {
	from {
		opacity: 0;
		transform: translate3d(0, -7px, 0);
	}
	to {
		opacity: 1;
		transform: translate3d(0, 0, 0);
	}
}

@keyframes prime-fade {
	from {
		opacity: 0;
	}
	to {
		opacity: 1;
	}
}

/* ══ OFF-RAMP 1 · explicit user switch ══════════════════════════════════
 * Independent of the OS setting, for users who simply prefer no motion.
 * The !important here is an accessibility-override, exempt from the
 * functional budget (I-5). 0.01ms rather than 0s so that transitionend /
 * animationend still fire and no plugin JS waiting on them hangs. */

body.prime-animations-off *,
body.prime-animations-off *::before,
body.prime-animations-off *::after {
	animation-duration: 0.01ms !important; /* a11y */
	animation-iteration-count: 1 !important; /* a11y */
	transition-duration: 0.01ms !important; /* a11y */
	scroll-behavior: auto !important; /* a11y */
}

/* ══ OFF-RAMP 2 · system preference ═════════════════════════════════════
 * Respected BY DEFAULT. `body:not(.prime-motion-force)` lets a user who
 * enables OS reduced-motion for unrelated reasons opt back in. */

@media (prefers-reduced-motion: reduce) {
	body:not(.prime-motion-force) *,
	body:not(.prime-motion-force) *::before,
	body:not(.prime-motion-force) *::after {
		animation-duration: 0.01ms !important; /* a11y */
		animation-iteration-count: 1 !important; /* a11y */
		transition-duration: 0.01ms !important; /* a11y */
		scroll-behavior: auto !important; /* a11y */
	}
}

/* ══ OFF-RAMP 3 · granular toggles ══════════════════════════════════════
 * No !important needed — these target specific properties on specific
 * elements, so ordinary cascade order suffices. */

body.prime-anim-no-hover-lift button:not(.clickable-icon):active {
	transform: none;
}

body.prime-anim-no-hover-lift input[type='range']::-webkit-slider-thumb:hover {
	transform: none;
}

/* ── PLATFORM · MOBILE & TABLET ────────────────────────────────────────────
 * NEW IN PRIME. Obsidianite had no mobile rules (defect F-19).
 * ──────────────────────────────────────────────────────────────────────── */

body.is-mobile {
	--prime-font-size: 16px;
	--prime-content-width: 100%;
}

/* ── Touch targets ────────────────────────────────────────────────────────
 * A 1.05em checkbox is comfortable with a mouse but small for a fingertip.
 * Because Prime's checkbox is the input itself, enlarging it is a single
 * token change — the marker scales automatically (it is at inset: 0) and
 * nothing needs repositioning. Under Obsidianite's parent-painted approach
 * this would have required recalculating every negative offset. */

body.is-mobile {
	--prime-checkbox-size: 1.25em;
	--prime-checkbox-gap: 0.7em;
}

body.is-phone .clickable-icon {
	padding: var(--prime-space-2);
}

/* ── Chrome ───────────────────────────────────────────────────────────── */

body.is-mobile .workspace-drawer {
	background-color: var(--prime-bg-primary-alt);
}

body.is-mobile .workspace-drawer-inner {
	background-color: var(--prime-bg-primary-alt);
}

body.is-mobile .mobile-navbar,
body.is-mobile .mobile-toolbar {
	background-color: var(--prime-bg-primary-alt);
	border-top: var(--prime-border-width) solid var(--prime-border);
}

body.is-mobile .mobile-toolbar-option:hover,
body.is-mobile .mobile-navbar-action:hover {
	color: var(--prime-accent);
}

/* The floating status bar is a desktop affordance; it overlaps content and
 * has no hover state on touch. */
body.is-mobile.prime-statusbar-floating .status-bar {
	position: static;
	opacity: 1;
	border-radius: 0;
	border-left: none;
}

/* ── Reading comfort ──────────────────────────────────────────────────── */

body.is-phone {
	--prime-h1-size: 1.75em;
	--prime-h2-size: 1.4em;
	--prime-h3-size: 1.2em;
	--prime-h-margin-top: 1.4em;
	--prime-divider-margin: 2em;
	--prime-quote-padding: var(--prime-space-2) var(--prime-space-3);
	--prime-code-padding: var(--prime-space-3);
}

body.is-phone .markdown-rendered pre {
	border-radius: var(--prime-radius-s);
}

/* Tables need horizontal scroll rather than compression */
body.is-mobile .markdown-rendered table {
	display: block;
	overflow-x: auto;
	white-space: nowrap;
}

/* Modals go full-bleed */
body.is-phone .modal {
	border-radius: var(--prime-radius-l) var(--prime-radius-l) 0 0;
}

/* ── Tablet ───────────────────────────────────────────────────────────── */

body.is-tablet {
	--prime-content-width: 680px;
}

