const fs = require('fs');
const { execSync } = require('child_process');
const css = fs.readFileSync('theme.css','utf8');
const m = css.match(/\/\*\s*@settings([\s\S]*?)\*\//);
const tmp = process.env.TEMP + '/opencode/ss.yaml';
fs.writeFileSync(tmp, m[1], 'utf8');
const out = execSync('npx --yes js-yaml "' + tmp + '"', { encoding: 'utf8', maxBuffer: 20e6 });
const c = JSON.parse(out);
console.log('name   :', c.name);
console.log('id     :', c.id);
console.log('entries:', c.settings.length);
const types = {};
c.settings.forEach(s => types[s.type] = (types[s.type]||0)+1);
console.log('types  :', JSON.stringify(types, null, 0));
const bad = c.settings.filter(s =>
  s.type && s.type.startsWith('variable-') &&
  s.default === undefined && !(s['default-light'] !== undefined && s['default-dark'] !== undefined));
console.log('variable settings missing a default:', bad.length, bad.map(s=>s.id).join(', '));
const badCls = c.settings.filter(s => (s.type==='class-select'||s.type==='class-toggle') && s.default === undefined);
console.log('class settings missing a default  :', badCls.length, badCls.map(s=>s.id).join(', '));
const ids = c.settings.filter(s=>s.type&&s.type.startsWith('variable-')).map(s=>s.id);
const dupes = ids.filter((x,i)=>ids.indexOf(x)!==i);
console.log('duplicate variable ids            :', dupes.length, [...new Set(dupes)].join(', '));
const missing = ids.filter(id => !new RegExp('--'+id.replace(/[-]/g,'\\-')+'\\s*:').test(css));
console.log('ids with no CSS variable          :', missing.length, missing.join(', '));
const opts = c.settings.filter(s=>s.type==='class-select').flatMap(s=>s.options.map(o=>o.value||o));
const noRule = opts.filter(v => !new RegExp('body\\.'+v+'\\b').test(css));
console.log('class-select options with no rule :', noRule.length, noRule.join(', '));
