@'
const fs = require('fs');
const hsla = /^((hsla)|hsl)[\D]+([\d.]+)[\D]+([\d.]+)[\D]+([\d.]+)[\D]*?([\d.]+|$)/i;

// Extract every default-light / default-dark / default colour value from our settings
const css = fs.readFileSync('theme.css','utf8');
const yaml = css.match(/\/\*\s*@settings([\s\S]*?)\*\//)[1];
const vals = [...yaml.matchAll(/^\s*default(?:-light|-dark)?:\s*'([^']+)'\s*$/gm)].map(m=>m[1]);
const colours = [...new Set(vals.filter(v=>/^(#|rgb|hsl)/.test(v)))];

console.log('=== Testing ' + colours.length + " distinct colour defaults against Pickr's real hsla regex ===\n");

const bad = [];
for (const c of colours) {
  const m = hsla.exec(c);
  if (!m) { bad.push([c,'NO MATCH']); continue; }
  // Pickr: group[6] is alpha. If absent/empty -> undefined -> alpha 1.
  const alpha = m[6] === '' || m[6] === undefined ? 1 : parseFloat(m[6]);
  const parsed = { h:+m[3], s:+m[4], l:+m[5], a:alpha };
  const suspicious = alpha !== 1;
  if (suspicious) bad.push([c, 'alpha parsed as ' + alpha]);
}

if (!bad.length) console.log('  All values parse with alpha = 1 (opaque).');
else {
  console.log('  PROBLEM VALUES (' + bad.length + '):');
  for (const [c,why] of bad) console.log('   ', c.padEnd(28), '->', why);
}

console.log('\n=== Specific worked examples ===');
for (const c of ['hsl(190, 87%, 45%)','hsla(190, 87%, 45%, 0.12)','hsla(192, 88%, 29%, 0.09)','hsl(0, 0%, 100%)']) {
  const m = hsla.exec(c);
  const alpha = (m[6] === '' || m[6] === undefined) ? 1 : parseFloat(m[6]);
  console.log('  ' + c.padEnd(30) + ' groups=[' + m.slice(3,7).map(x=>x===''?'(empty)':x).join(', ') + ']  alpha=' + alpha);
}
'@ | Set-Content -LiteralPath "C:\Users\gupta\AppData\Local\Temp\opencode\pickr2.cjs" -Encoding UTF8; node "C:\Users\gupta\AppData\Local\Temp\opencode\pickr2.cjs"

