	font-size: var(--prime-divider-glyph-size);
	line-height: 1;
	color: var(--prime-divider-glyph-color);
	background-color: var(--prime-divider-glyph-bg);
	pointer-events: none;
	transition: transform var(--prime-motion-moderate) var(--prime-ease-overshoot),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

/* Dividers in tight contexts get less breathing room */
.markdown-embed .markdown-rendered hr,
.hover-popover .markdown-rendered hr,
.canvas-node-content .markdown-rendered hr,
.callout .markdown-rendered hr {
