/* ── COMPONENT · DIVIDERS (hr) ─────────────────────────────────────────────
 *
 * Base implementation. All five visual styles live in
 * src/variants/70-variants-dividers.css and only reassign tokens.
 *
 * ── PHASE 1 REDESIGN · WHY THE hr IS NOW A BOX, NOT A BORDER ────────────
 *
 * The original implementation drew the rule with `border-bottom` on a
 * zero-height element. That gave every variant the same underlying shape,
 * so Decorative / Gradient / Animated could differ only by colour — which
 * is exactly the complaint.
 *
 * The rule is now a real box with a background, which unlocks FIVE
 * independent structural axes that variants can combine:
 *
 *   1. --prime-divider-style      solid | dashed | dotted | double
 *   2. --prime-divider-width      the rule need not span the full measure
 *   3. --prime-divider-image      a gradient fill instead of a flat colour
 *   4. --prime-divider-cap-*      dots at each end
 *   5. --prime-divider-shimmer-*  a travelling highlight
 *
 * Because the differences are geometric, the variants stay distinguishable
 * even when the user sets every colour to the same value — which was the
 * explicit requirement.
 *
 * Dashed/dotted are produced with a repeating-linear-gradient rather than a
 * border-style so that they compose with --prime-divider-image and keep
 * working at fractional thicknesses.
 *
 * ── KNOWN LIMITATION (unchanged, documented) ────────────────────────────
 * The Decorative glyph punches a hole in the rule using
 * --prime-divider-glyph-bg. Inside a callout or blockquote — which have a
 * different background — that hole will be the wrong colour. Prefer the
 * Gradient or Minimal style there. See docs/08 §3.3.
 * ──────────────────────────────────────────────────────────────────────── */

.markdown-rendered hr,
.markdown-source-view.mod-cm6 .cm-line hr {
	position: relative;
	box-sizing: content-box;
	border: none;
	height: var(--prime-divider-thickness);
	width: var(--prime-divider-width);
	margin-inline: auto;
	margin-block: var(--prime-divider-space-above) var(--prime-divider-space-below);
	opacity: var(--prime-divider-opacity);
	overflow: visible;

	/* Flat colour by default; a variant may replace this with a gradient. */
	background-color: var(--prime-divider-color);
	background-image: var(--prime-divider-image);
	background-repeat: no-repeat;
	border-radius: var(--prime-radius-pill);
}

/* ── Dash / dot patterns ──────────────────────────────────────────────────
 * Applied as a mask so the pattern composes with whatever fill (flat or
 * gradient) the variant has chosen. */

body.prime-divider-dashed .markdown-rendered hr,
body.prime-divider-dashed .markdown-source-view.mod-cm6 .cm-line hr {
	-webkit-mask-image: repeating-linear-gradient(
		to right,
		#000 0 10px,
		transparent 10px 18px
	);
	mask-image: repeating-linear-gradient(to right, #000 0 10px, transparent 10px 18px);
}

body.prime-divider-dotted .markdown-rendered hr,
body.prime-divider-dotted .markdown-source-view.mod-cm6 .cm-line hr {
	-webkit-mask-image: repeating-linear-gradient(
		to right,
		#000 0 2px,
		transparent 2px 8px
	);
	mask-image: repeating-linear-gradient(to right, #000 0 2px, transparent 2px 8px);
}

/* ── End caps ─────────────────────────────────────────────────────────────
 * Two dots pinned to the ends of the rule. Drawn with a single ::before
 * using two background gradients, keeping the ::after free for the glyph. */

.markdown-rendered hr::before,
.markdown-source-view.mod-cm6 .cm-line hr::before {
	content: '';
	display: var(--prime-divider-cap-display);
	position: absolute;
	top: 50%;
	left: calc(-1 * var(--prime-divider-cap-size) / 2);
	right: calc(-1 * var(--prime-divider-cap-size) / 2);
	height: var(--prime-divider-cap-size);
	transform: translateY(-50%);
	pointer-events: none;
	background-image: radial-gradient(
			circle at left center,
			var(--prime-divider-color) 0 calc(var(--prime-divider-cap-size) / 2),
			transparent calc(var(--prime-divider-cap-size) / 2)
		),
		radial-gradient(
			circle at right center,
			var(--prime-divider-color) 0 calc(var(--prime-divider-cap-size) / 2),
			transparent calc(var(--prime-divider-cap-size) / 2)
		);
	background-repeat: no-repeat;
	background-size: 50% 100%, 50% 100%;
	background-position: left center, right center;
}

/* ── Decorative glyph ─────────────────────────────────────────────────────
 * `--prime-divider-glyph-gap` controls the clearance punched in the rule,
 * independently of the glyph's own font size (Phase 2). */

.markdown-rendered hr::after,
.markdown-source-view.mod-cm6 .cm-line hr::after {
	content: var(--prime-divider-glyph);
	display: var(--prime-divider-glyph-display);
	position: absolute;
	left: 50%;
	top: 50%;
	transform: translate(-50%, -50%) rotate(var(--prime-divider-glyph-rotate));
	transform-origin: 50% 50%;
	padding-inline: var(--prime-divider-glyph-gap);
	font-size: var(--prime-divider-glyph-size);
	font-weight: var(--prime-divider-glyph-weight);
	line-height: 1;
	color: var(--prime-divider-glyph-color);
	background-color: var(--prime-divider-glyph-bg);
	pointer-events: none;
	transition: transform var(--prime-motion-moderate) var(--prime-ease-overshoot),
		color var(--prime-motion-fast) var(--prime-ease-standard);
}

/* ── Tight contexts ───────────────────────────────────────────────────── */

.markdown-embed .markdown-rendered hr,
.hover-popover .markdown-rendered hr,
.canvas-node-content .markdown-rendered hr,
.callout .markdown-rendered hr {
	margin-block: 1.2em;
}

/* ── VARIANTS · DIVIDERS ───────────────────────────────────────────────────
 *
 * PHASE 1 REDESIGN — each style now has a distinct STRUCTURAL identity.
 *
 * The previous set was criticised, correctly, for being colour-only:
 * Decorative / Gradient / Animated shared one shape, and Standard / Minimal
 * differed only in spacing.
 *
 * Each style now differs on at least two geometric axes, so all five remain
 * distinguishable even if the user sets every colour token identically:
 *
 *   Style        Fill        Width  Thick  Caps  Glyph  Motion
 *   ─────────────────────────────────────────────────────────────────────
 *   Standard     flat        100%   2px    dots  no     none
 *   Minimal      flat         38%   1px    no    no     none
 *   Gradient     gradient    100%   2px    no    no     none
 *   Decorative   gradient     92%   1px    no    YES    hover only
 *   Animated     gradient    100%   2px    no    no     YES travelling
 *
 * Contract (docs/08 §2): a variant may only reassign component tokens or
 * toggle a decorative pseudo-element's display. Exactly one variant class is
 * always present on <body>.
 * ──────────────────────────────────────────────────────────────────────── */

/* ══ STANDARD ═══════════════════════════════════════════════════════════
 * A confident, conventional rule: full width, noticeably thicker than
 * Minimal, flat colour, with small dots at each end that give it a
 * deliberate "typeset" finish. No gradient, no glyph. */

body.prime-divider-standard {
	--prime-divider-thickness: 2px;
	--prime-divider-width: 100%;
	--prime-divider-image: none;
	--prime-divider-glyph-display: none;
	--prime-divider-cap-display: block;
	--prime-divider-cap-size: 5px;
	--prime-divider-shimmer-display: none;
	--prime-divider-opacity: 1;
}

/* ══ MINIMAL ════════════════════════════════════════════════════════════
 * A short, hairline, centred rule — a breath rather than a barrier.
 * Distinguished from Standard by WIDTH (38% vs 100%), thickness, no caps
 * and tighter spacing. The width difference alone keeps them separable at
 * any colour. */

body.prime-divider-minimal {
	--prime-divider-thickness: 1px;
	--prime-divider-width: 38%;
	--prime-divider-image: none;
	--prime-divider-glyph-display: none;
	--prime-divider-cap-display: none;
	--prime-divider-shimmer-display: none;
	--prime-divider-space-above: 1.6em;
	--prime-divider-space-below: 1.6em;
	--prime-divider-opacity: 0.5;
}

/* ══ GRADIENT ═══════════════════════════════════════════════════════════
 * A full-bleed band that fades in from nothing, peaks at the centre and
 * fades out again. No glyph, no caps — its identity is the soft-edged
 * horizontal wash, which is visibly different from Standard's hard,
 * end-capped rule even in a single colour. */

body.prime-divider-gradient {
	--prime-divider-thickness: 2px;
	--prime-divider-width: 100%;
	--prime-divider-image: linear-gradient(
		90deg,
		transparent 0%,
		var(--prime-divider-grad-1) 28%,
		var(--prime-divider-grad-2) 72%,
		transparent 100%
	);
	--prime-divider-glyph-display: none;
	--prime-divider-cap-display: none;
	--prime-divider-shimmer-display: none;
	--prime-divider-opacity: 1;
}

/* Gradient fills the box, so the flat colour underneath must not show. */
body.prime-divider-gradient .markdown-rendered hr,
body.prime-divider-gradient .markdown-source-view.mod-cm6 .cm-line hr {
	background-color: transparent;
	background-size: 100% 100%;
}

/* ══ DECORATIVE ═════════════════════════════════════════════════════════
 * The Obsidianite signature, preserved: a fading rule interrupted by a
 * rotated centred glyph. Kept structurally distinct from Gradient by the
 * glyph itself plus a slightly inset width and a thinner rule, so the two
 * never read as the same thing. */

body.prime-divider-decorative {
	--prime-divider-thickness: 1px;
	--prime-divider-width: 92%;
	--prime-divider-image: linear-gradient(
		90deg,
		transparent 0%,
		var(--prime-divider-grad-1) 30%,
		var(--prime-divider-grad-2) 70%,
		transparent 100%
	);
	--prime-divider-glyph-display: inline-block;
	--prime-divider-cap-display: none;
	--prime-divider-shimmer-display: none;
	--prime-divider-opacity: 1;
}

body.prime-divider-decorative .markdown-rendered hr,
body.prime-divider-decorative .markdown-source-view.mod-cm6 .cm-line hr {
	background-color: transparent;
	background-size: 100% 100%;
	overflow: visible;
}

/* A gentle hover response — the glyph settles back to upright. */
body.prime-divider-decorative:not(.prime-animations-off)
	.markdown-rendered
	hr:hover::after {
	transform: translate(-50%, -50%) rotate(0deg) scale(1.1);
	color: var(--prime-accent);
}

/* ══ ANIMATED ═══════════════════════════════════════════════════════════
 * A genuinely moving divider: a bright highlight travels along the rule on
 * a slow loop. This is NOT the static Gradient appearance with a hover
 * effect bolted on — the motion is the identity.
 *
 * Performance: the shimmer is a separate absolutely-positioned ::before
 * layer animated purely with `transform: translate3d`. No background-
 * position animation (which repaints), no layout properties, no filter.
 * The base rule underneath is deliberately dimmed so the travelling
 * highlight has something to read against.
 *
 * Note this variant reassigns --prime-divider-cap-display to none and
 * reuses ::before for the shimmer, which is why caps and shimmer are
 * mutually exclusive by design. */

body.prime-divider-animated {
	--prime-divider-thickness: 2px;
	--prime-divider-width: 100%;
	--prime-divider-image: linear-gradient(
		90deg,
		transparent 0%,
		var(--prime-divider-grad-1) 30%,
		var(--prime-divider-grad-2) 70%,
		transparent 100%
	);
	--prime-divider-glyph-display: none;
	--prime-divider-cap-display: none;
	--prime-divider-shimmer-display: block;
	--prime-divider-opacity: 0.55;
}

body.prime-divider-animated .markdown-rendered hr,
body.prime-divider-animated .markdown-source-view.mod-cm6 .cm-line hr {
	background-color: transparent;
	background-size: 100% 100%;
	overflow: hidden; /* clip the travelling highlight to the rule */
}

/* The travelling highlight. ::before is repurposed from the end caps. */
body.prime-divider-animated .markdown-rendered hr::before,
body.prime-divider-animated .markdown-source-view.mod-cm6 .cm-line hr::before {
	content: '';
	display: var(--prime-divider-shimmer-display);
	position: absolute;
	inset: 0 auto 0 0;
	width: var(--prime-divider-shimmer-width);
	height: 100%;
	transform: translate3d(0, 0, 0);
	background-image: linear-gradient(
		90deg,
		transparent,
		var(--prime-divider-color),
		transparent
	);
	background-size: 100% 100%;
	will-change: auto;
	pointer-events: none;
	animation: prime-divider-shimmer var(--prime-divider-shimmer-duration) linear infinite;
}

/* Respect the global animation switch — degrade to a static rule at full
 * opacity so the divider never looks half-finished. */
body.prime-divider-animated.prime-animations-off {
	--prime-divider-opacity: 1;
	--prime-divider-shimmer-display: none;
}

/* prefers-reduced-motion is handled globally in systems/81-motion.css, but
 * the shimmer is purely decorative so it is removed outright rather than
 * merely shortened to 0.01ms (which would leave it frozen mid-track). */
@media (prefers-reduced-motion: reduce) {
	body.prime-divider-animated:not(.prime-motion-force) {
		--prime-divider-opacity: 1;
		--prime-divider-shimmer-display: none;
	}
}

