input.newString:
@keyframes prime-fade {
	from {
		opacity: 0;
	}
	to {
		opacity: 1;
	}
}

/* Phase 1 — the Animated divider's travelling highlight.
 * transform-only, so it runs on the compositor. The element is
 * --prime-divider-shimmer-width wide; translating from -100% of itself to
 * (100/width)% of the track sweeps it fully across and off the far end. */
@keyframes prime-divider-shimmer {
	from {
		transform: translate3d(-100%, 0, 0);
	}
	to {
		transform: translate3d(calc(100vw + 100%), 0, 0);
	}
}

/* Phase 3 — the active-tab indicator wipes in from the centre rather than
 * simply appearing. scaleX only; no layout, no repaint of the tab itself. */
@keyframes prime-tab-indicator-in {
	from {
		transform: scaleX(0);
		opacity: 0;
	}
	to {
		transform: scaleX(1);
		opacity: 1;
	}
}

/* Phase 3 — a newly-activated tab settles into place. Deliberately subtle:
 * a 2px rise with a slight overshoot, matching the button vocabulary. */
@keyframes prime-tab-activate {
	from {
		transform: translateY(2px);
	}
	to {
		transform: translateY(0);
	}
}

