/* ── Indented (non-fenced) code ───────────────────────────────────────── */

.cm-s-obsidian .cm-hmd-indented-code {
	color: var(--prime-code-color);
	font-family: var(--prime-font-monospace);
}

/* ══════════════════════════════════════════════════════════════════════════
 *  PHASE 6 · CODE BLOCK LINE NUMBERS
 * ══════════════════════════════════════════════════════════════════════════
 *
 * ── DOM INVESTIGATION (done before implementing, per instruction) ───────
 *
 * LIVE PREVIEW (CodeMirror 6)
 *   Every source line is its own element:
 *       <div class="cm-line HyperMD-codeblock HyperMD-codeblock-bg">…</div>
 *   with .HyperMD-codeblock-begin / -end marking the ``` fences.
 *   Discrete sibling elements → CSS counters work reliably.        ✅
 *
 * READING MODE (Prism)
 *   Obsidian emits ONE text node containing newline characters:
 *       <pre><code class="language-js">line1\nline2\nline3</code></pre>
 *   There is no per-line element. CSS counters increment per ELEMENT, and
 *   there is no selector that can address a line of text inside a text
 *   node. CSS-only line numbering is therefore STRUCTURALLY IMPOSSIBLE
 *   here — not merely difficult.                                    ❌
 *
 *   Corroborating evidence: Obsidianite shipped ~40 lines of Prism
 *   line-number CSS (its lines 1442-1481) targeting
 *   `.line-numbers-rows > span`. That DOM is generated by the Prism
 *   line-numbers JAVASCRIPT plugin, which Obsidian does not bundle. The
 *   selectors never matched anything, which is why the feature never
 *   worked in Obsidianite either. Prime does not repeat that mistake.
 *
 *   Approaches considered and rejected for Reading Mode:
 *     · repeating-linear-gradient "ruler" — cannot show digits, and
 *       desynchronises the moment a line wraps
 *     · ::before with a hard-coded digit string — wrong for any length
 *     · counters on .token spans — tokens do not map 1:1 to lines
 *   Each is a fragile hack. Per the instruction, the limitation is
 *   documented instead. A future release may add numbering via a small
 *   companion snippet or by shipping the Prism plugin.
 *
 * ── WHAT THIS IMPLEMENTATION DOES NOT TOUCH ─────────────────────────────
 *   syntax highlighting · scrolling · wrapping · copy button ·
 *   language flair · plugin-rendered blocks · the code text itself
 *
 * The numbers are drawn on a ::before pseudo-element of each code line and
 * are `user-select: none`, so selecting and copying code yields the code
 * only — never the numbers.
 * ────────────────────────────────────────────────────────────────────── */

body.prime-linenum-on .markdown-source-view.mod-cm6 .HyperMD-codeblock-begin {
	counter-reset: prime-codeline;
}

body.prime-linenum-on
	.markdown-source-view.mod-cm6
	.HyperMD-codeblock:not(.HyperMD-codeblock-begin):not(.HyperMD-codeblock-end) {
	counter-increment: prime-codeline;
	/* Reserve the gutter without disturbing the block's own padding. */
	padding-inline-start: calc(
		var(--prime-code-padding) + var(--prime-linenum-width) + var(--prime-linenum-gap)
	) !important; /* a11y-exempt: overrides CM6 inline padding — see note below */
	position: relative;
}

body.prime-linenum-on
	.markdown-source-view.mod-cm6
	.HyperMD-codeblock:not(.HyperMD-codeblock-begin):not(.HyperMD-codeblock-end)::before {
	content: counter(prime-codeline);
	position: absolute;
	left: var(--prime-code-padding);
	width: var(--prime-linenum-width);
	text-align: right;
	color: var(--prime-linenum-color);
	opacity: var(--prime-linenum-opacity);
	font-family: var(--prime-font-monospace);
	font-size: var(--prime-linenum-size);
	font-variant-numeric: tabular-nums;
	line-height: inherit;
	user-select: none;
	-webkit-user-select: none;
	pointer-events: none;
}

/* Optional separator rule between gutter and code. */
body.prime-linenum-on
	.markdown-source-view.mod-cm6
	.HyperMD-codeblock:not(.HyperMD-codeblock-begin):not(.HyperMD-codeblock-end)::after {
	content: '';
	position: absolute;
	top: 0;
	bottom: 0;
	left: calc(var(--prime-code-padding) + var(--prime-linenum-width) + var(--prime-linenum-gap) / 2);
	width: var(--prime-linenum-divider-width);
	background-color: var(--prime-code-border);
	pointer-events: none;
}

