  'prime-link-external-accent','prime-inline-code-bg','prime-quote-bg',
  'prime-tag-bg','prime-table-border-color'
]);

const lines = text.split('\n');
let currentId = null, currentType = null, removed = 0;
const out = [];

for (let i = 0; i < lines.length; i++) {
  const L = lines[i];
  const idM = L.match(/^\s*id:\s*(\S+)\s*$/);
  if (idM) { currentId = idM[1]; currentType = null; }
  const tM = L.match(/^\s*type:\s*(\S+)\s*$/);
