input.newString:
/* ── Dividers ─────────────────────────────────────────────────────────────
 * The three gradient-based divider styles set `background-color: transparent`
 * because their gradient IMAGE provides the fill. Removing the image alone
 * would therefore leave an invisible rule — so the flat colour must be
 * restored in the same breath. Both halves are required; neither is
 * sufficient on its own.
 *
 * The styles remain mutually distinguishable with gradients off, because
 * their differences are geometric (width, thickness, caps, glyph, motion)
 * rather than chromatic — which was the point of the Phase 1 redesign. */

body.prime-gradients-off {
	--prime-divider-gradient: none;
}

body.prime-gradients-off.prime-divider-gradient,
body.prime-gradients-off.prime-divider-decorative,
body.prime-gradients-off.prime-divider-animated {
	--prime-divider-image: none;
}

body.prime-gradients-off.prime-divider-gradient .markdown-rendered hr,
body.prime-gradients-off.prime-divider-gradient .markdown-source-view.mod-cm6 .cm-line hr,
body.prime-gradients-off.prime-divider-decorative .markdown-rendered hr,
body.prime-gradients-off.prime-divider-decorative .markdown-source-view.mod-cm6 .cm-line hr,
body.prime-gradients-off.prime-divider-animated .markdown-rendered hr,
body.prime-gradients-off.prime-divider-animated .markdown-source-view.mod-cm6 .cm-line hr {
	background-color: var(--prime-divider-color);
}

/* The Animated style's travelling highlight is a gradient too. With
 * gradients off it becomes a plain moving block, which looks wrong — so the
 * shimmer is retired and the rule returns to full opacity. */
body.prime-gradients-off.prime-divider-animated {
	--prime-divider-shimmer-display: none;
	--prime-divider-opacity: 1;
}

