const fs = require('fs');
const raw = fs.readFileSync('theme.css','utf8');
const css = raw.replace(/\/\*[\s\S]*?\*\//g,'');
let pass=0, fail=0;
const t=(l,c)=>{ c?pass++:fail++; console.log((c?'  PASS  ':'  FAIL  ')+l); };
const H=(s)=>console.log('\n=== '+s+' ===');

H('PHASE 1 : five structurally distinct dividers');
const V=['standard','minimal','gradient','decorative','animated'];
V.forEach(v=>t('variant body.prime-divider-'+v+' exists', new RegExp('body\\.prime-divider-'+v+'\\s*\\{').test(css)));
// distinctness matrix: each must differ on >=2 geometric axes
const grab=(v,tok)=>{const m=css.match(new RegExp('body\\.prime-divider-'+v+'\\s*\\{([^}]*)\\}'));if(!m)return null;const g=m[1].match(new RegExp('--prime-divider-'+tok+':\\s*([^;]+)'));return g?g[1].trim():null;};
const axes=['thickness','width','cap-display','glyph-display','shimmer-display'];
const sig={};V.forEach(v=>sig[v]=axes.map(a=>grab(v,a)).join('|'));
V.forEach(v=>console.log('    '+v.padEnd(11)+' -> '+sig[v]));
const uniq=new Set(Object.values(sig));
t('all five signatures are unique', uniq.size===5);
t('Standard vs Minimal differ in width', grab('standard','width')!==grab('minimal','width'));
t('Gradient vs Decorative differ (glyph)', grab('gradient','glyph-display')!==grab('decorative','glyph-display'));
t('Animated has shimmer, Gradient does not', grab('animated','shimmer-display')==='block' && grab('gradient','shimmer-display')==='none');
t('shimmer keyframe is transform-only', /@keyframes prime-divider-shimmer\s*\{[^@]*?\}\s*\}/.test(css) && !/@keyframes prime-divider-shimmer[\s\S]{0,300}background-position/.test(css));
t('Animated respects prefers-reduced-motion', /prefers-reduced-motion[\s\S]{0,400}prime-divider-animated/.test(css));
t('Animated respects global anim toggle', /prime-divider-animated\.prime-animations-off/.test(css));

H('PHASE 2 : dimension controls');
['space-above','space-below','thickness','width','glyph-size','glyph-gap','cap-size'].forEach(k=>
  t('token --prime-divider-'+k, new RegExp('--prime-divider-'+k+'\\s*:').test(css)));
t('token --prime-h-underline-padding', /--prime-h-underline-padding\s*:/.test(css));
t('token --prime-highlight-padding-x', /--prime-highlight-padding-x\s*:/.test(css));
t('token --prime-highlight-padding-y', /--prime-highlight-padding-y\s*:/.test(css));

H('PHASE 3 : tab animations');
t('hover lift uses translateY', /workspace-tab-header:not\(\.is-active\):hover\s*\{[^}]*translateY\(calc\(-1 \* var\(--prime-tab-lift\)\)\)/.test(css));
t('press sink uses translateY', /workspace-tab-header:not\(\.is-active\):active\s*\{[^}]*translateY\(var\(--prime-tab-press\)\)/.test(css));
t('active tab raised-card box-shadow', /workspace-tab-header\.is-active\s*\{[^}]*inset 0 1px 0 0/.test(css));
t('indicator wipe keyframe', /@keyframes prime-tab-indicator-in/.test(css));
t('activate keyframe', /@keyframes prime-tab-activate/.test(css));
t('close button scales in', /workspace-tab-header-inner-close-button[\s\S]{0,300}transform:\s*scale\(0\.85\)/.test(css));
t('close button fills with accent', /close-button:hover[\s\S]{0,150}background-color:\s*var\(--prime-accent\)/.test(css));
t('tab motion honours global toggle', /body:not\(\.prime-animations-off\) \.workspace-tab-header\.is-active/.test(css));
t('granular tab opt-out exists', /body\.prime-anim-no-tabs/.test(css));
t('mobile keeps close button visible', /is-mobile \.workspace-tab-header-inner-close-button/.test(css));
t('no layout-triggering tab animation', !/workspace-tab-header[^}]*transition:[^;]*\b(width|height|margin|padding)\b/.test(css));

H('PHASE 4 : glow system');
