 if(e.isDirectory())walk(p,out);
 else if(exts.has(path.extname(e.name))||e.name==='LICENSE')out.push(p);} return out;}

// ORDER MATTERS. Longest / most specific first.
const RULES=[
  [/Obsidian Prime/g,           'Primidian'],
  [/OBSIDIAN PRIME/g,           'PRIMIDIAN'],
  [/obsidian-prime/g,           'primidian'],
