  let t=fs.readFileSync(f,'utf8'); const orig=t;
  let hits=0;
  for(const [re,to] of RULES){
    const m=t.match(re);
    if(m){ perRule[re.source]=(perRule[re.source]||0)+m.length; hits+=m.length; t=t.replace(re,to); }
