@'
const fs=require('fs');
const raw=fs.readFileSync('theme.css','utf8');
const css=raw.replace(/\/\*[\s\S]*?\*\//g,'');
const flat=css.replace(/\s+/g,' ');
let pass=0,fail=0;
const t=(l,c)=>{c?pass++:fail++;console.log((c?'  PASS  ':'  FAIL  ')+l);};
const H=s=>console.log('\n=== '+s+' ===');

H('RENAME COMPLETENESS');
t('no --prime- tokens remain',      !/--prime-/.test(raw));
t('no body.prime- classes remain',  !/body\.prime-/.test(raw));
t('no "Obsidian Prime" remains',    !/Obsidian Prime/.test(raw));
t('no standalone "Prime" remains',  !/\bPrime\b/.test(raw));
t('no data-prime-slot remains',     !/data-prime-slot/.test(raw));
t('--primidian- tokens present',    /--primidian-accent/.test(raw));
t('body.primidian- classes present',/body\.primidian-gradients-off/.test(raw));

H('THIRD-PARTY ATTRIBUTION PRESERVED');
t('"Primary" still credited',        /\bPrimary\b/.test(raw));
t('primary-theme repo URL intact',   /github\.com\/primary-theme\/obsidian/.test(raw));
t('ko-fi/ceciliamay intact',         /ko-fi\.com\/ceciliamay/.test(raw));
t('Obsidianite credited',            /Obsidian-Obsidianite/.test(raw));
t('no-Primary-code statement intact',/NO CODE FROM PRIMARY IS INCLUDED/i.test(raw));

H('OBSIDIAN VARIABLES UNHARMED (the prim-a-ry trap)');
['--background-primary','--background-primary-alt','--text-normal','--interactive-accent-rgb','--checkbox-size']
  .forEach(v=>t('bridge assigns '+v, new RegExp(v.replace(/-/g,'\\-')+'\\s*:').test(css)));
t('--primidian-bg-primary kept its "primary"', /--primidian-bg-primary\s*:/.test(css));

H('FUNCTIONALITY REGRESSION');
t('Bug#1 no opacity:0 on checkbox', !/input\[type='checkbox'\]\s*\{[^}]*opacity:\s*0\b/.test(css));
t('Bug#1 marker on input::after',   /input\[type='checkbox'\]::after\s*\{[\s\S]{0,200}inset:\s*0/.test(css));
t('Bug#1 TLK data-task path',       /input\[type='checkbox'\]:checked\[data-task=/.test(css));
t('Bug#2 markdown-rendered code',   /\.markdown-rendered code:not\(pre > code\)/.test(css));
t('Bug#2 fill-color set',           /\.markdown-rendered code:not\(pre > code\)[\s\S]{0,400}-webkit-text-fill-color/.test(css));
t('Bug#2 :has() guard',             /:not\(\s*:has\(code, kbd, mark, a/.test(css));
t('5 divider variants',             ['standard','minimal','gradient','decorative','animated'].every(v=>new RegExp('body\\.primidian-divider-'+v+'\\s*\\{').test(css)));
t('glow system present',            /--primidian-glow-alpha:\s*clamp/.test(flat.replace(/ /g,'')) || /--primidian-glow-alpha/.test(css));
t('tab motion present',             /--primidian-tab-lift/.test(css));
t('line numbers present',           /counter-increment:\s*primidian-codeline/.test(css));
t('shimmer keyframe renamed',       /@keyframes primidian-divider-shimmer/.test(css));
t('no transition: all',             !/transition:\s*all\b/.test(css));
const imp=raw.split('\n').filter(l=>l.includes('!important')&&!/^\s*\*/.test(l));
t('functional !important == 0',     imp.every(l=>/a11y/.test(l)));

console.log('\n────────────────────');
console.log('  '+pass+' passed, '+fail+' failed');
