const fs=require('fs'),path=require('path');
const skip=/[\\\/]references[\\\/]|Primary\.css|Obsidianite\.css|node_modules/;
function walk(d,out=[]){for(const e of fs.readdirSync(d,{withFileTypes:true})){
 const p=path.join(d,e.name); if(skip.test(p))continue;
 if(e.isDirectory())walk(p,out); else if(/\.(md|css|json)$/.test(e.name)||e.name==='LICENSE')out.push(p);} return out;}
console.log('=== PROSE SANITY: phrases that may read oddly after a blind replace ===\n');
const bad=[
 [/Primidian is using/i,'"Primidian is using" (was Primary licence text?)'],
 [/Primidian Theme Settings/i,'Primidian Theme Settings (was Primary\'s settings block?)'],
 [/Primidian by Cecilia/i,'MISATTRIBUTION: Primidian by Cecilia'],
 [/Primidian-inspired/i,'"Primidian-inspired" (should be Primary-inspired)'],
 [/inspired by\s+Primidian/i,'"inspired by Primidian" (should be Primary)'],
 [/reconnaissance-Primidian/i,'doc filename reference broken'],
 [/Primidian\.css/i,'"Primidian.css" (should be Primary.css)'],
];
let n=0;
for(const f of walk(process.cwd())){
  const lines=fs.readFileSync(f,'utf8').split('\n');
  lines.forEach((l,i)=>{ for(const [re,msg] of bad){ if(re.test(l)){ n++;
    console.log(path.relative(process.cwd(),f)+':'+(i+1)+'  ['+msg+']');
    console.log('    '+l.trim().slice(0,150)); } } });
}
console.log(n?'\ntotal suspicious: '+n:'  none found - prose is clean');
